-- ============================================================================
-- Voltera Electronics Encyclopedia -- 01_update_components.sql
-- Schema upgrade + full replacement of the components catalog with the
-- curated set of 100 real electronics components.
-- Safe to run directly in the Supabase SQL Editor.
-- ============================================================================

-- 1. Schema additions (idempotent - safe to re-run) --------------------------
alter table public.components add column if not exists manufacturer text;
alter table public.components add column if not exists working_principle text;
alter table public.components add column if not exists applications text;
alter table public.components add column if not exists advantages text;
alter table public.components add column if not exists disadvantages text;
alter table public.components add column if not exists datasheet_url text;

-- Rebuild the full-text search index so it also covers manufacturer, tags,
-- and the long description -- not just name/category/short_description.
drop index if exists components_search_idx;
alter table public.components drop column if exists search_vector;
alter table public.components add column search_vector tsvector generated always as (
  setweight(to_tsvector('english', coalesce(name, '')), 'A') ||
  setweight(to_tsvector('english', coalesce(category, '')), 'B') ||
  setweight(to_tsvector('english', coalesce(manufacturer, '')), 'B') ||
  setweight(to_tsvector('english', coalesce(array_to_string(tags, ' '), '')), 'B') ||
  setweight(to_tsvector('english', coalesce(short_description, '')), 'C') ||
  setweight(to_tsvector('english', coalesce(long_description, '')), 'D')
) stored;
create index if not exists components_search_idx on public.components using gin (search_vector);
create index if not exists components_category_idx on public.components (category);
create index if not exists components_manufacturer_idx on public.components (manufacturer);

-- 2. Wipe the old placeholder / demo catalog ----------------------------------
-- Cascades to component_pins and favorites via existing FK ON DELETE CASCADE.
delete from public.components;

-- 3. Insert the curated 100-component catalog ---------------------------------

insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('carbon-film-resistor', 'Carbon Film Resistor', 'Resistors', 'Yageo', 'Fixed axial-lead resistor made from a carbon film deposited on a ceramic core.', 'The carbon film resistor is the classic general-purpose fixed resistor found in almost every through-hole hobby circuit. A thin carbon film is deposited on a small ceramic rod and helically cut to trim it to the target resistance, then coated in an insulating lacquer and marked with color bands.', 'Current flowing through the carbon film encounters a fixed resistive path set by the film thickness and the helical cut length; the film resistivity converts electrical energy into heat according to Ohms law, limiting current in proportion to the applied voltage.', 'Current limiting for LEDs, pull-up and pull-down networks, voltage dividers, biasing transistor circuits, general breadboard prototyping.', 'Very inexpensive, widely available in E12/E24 value series, stable enough for most hobby and educational work.', 'Wider tolerance and worse temperature stability than metal film types; generates more thermal noise, unsuitable for precision analog work.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Electronic-Axial-Lead-Resistors-Array.jpg', NULL, NULL, '{"Resistance Range": "1ohm-10Mohm", "Tolerance": "+/-5%", "Power Rating": "0.25W / 0.5W", "Package": "Axial THT", "Temp. Coefficient": "-200 to -500 ppm/C"}'::jsonb, '{"resistor","passive","carbon film","through-hole","beginner"}', 'beginner')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
  working_principle = excluded.working_principle, applications = excluded.applications,
  advantages = excluded.advantages, disadvantages = excluded.disadvantages,
  image_url = excluded.image_url, model_url = excluded.model_url, datasheet_url = excluded.datasheet_url,
  specs = excluded.specs, tags = excluded.tags, difficulty = excluded.difficulty;

insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('metal-film-resistor', 'Metal Film Resistor', 'Resistors', 'Vishay', 'Precision axial resistor using a sputtered metal alloy film for tight tolerance and low noise.', 'Metal film resistors replace the carbon film with a nickel-chromium alloy layer sputtered onto a ceramic substrate, then laser-trimmed for accuracy. They are the default choice whenever a circuit needs tight tolerance or a resistance value that must stay stable across temperature.', 'A thin metal alloy film provides a precisely controlled resistive path; because metal alloys have a much lower and more linear temperature coefficient than carbon, resistance drifts far less as the component heats up.', 'Precision voltage references, audio circuits, instrumentation amplifiers, filter networks, any design specifying 1% tolerance or better.', 'Tight tolerance down to +/-1% or better, low temperature coefficient, low noise compared to carbon film.', 'Costs more than carbon film equivalents; can be damaged by transient surge currents more easily than wirewound types.', NULL, NULL, 'https://www.vishay.com/docs/31003/cmf.pdf', '{"Resistance Range": "1ohm-1Mohm", "Tolerance": "+/-1%", "Power Rating": "0.25W / 0.6W", "Package": "Axial THT", "Temp. Coefficient": "+/-50 to +/-100 ppm/C"}'::jsonb, '{"resistor","passive","metal film","precision"}', 'beginner')
