  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
  working_principle = excluded.working_principle, applications = excluded.applications,
  advantages = excluded.advantages, disadvantages = excluded.disadvantages,
  image_url = excluded.image_url, model_url = excluded.model_url, datasheet_url = excluded.datasheet_url,
