insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('potentiometer', 'Rotary Potentiometer', 'Resistors', 'Bourns', 'Three-terminal variable resistor adjusted by turning a shaft, used to set voltage or resistance by hand.', 'A potentiometer pairs a resistive track with a wiper that slides along it as the shaft is rotated, producing an adjustable voltage divider. Panel-mount versions with a knob are common in volume controls, while PCB-mount versions are used for calibration.', 'The resistive element runs between two fixed terminals; the wiper terminal taps the track at a position set by the shaft angle, so the voltage at the wiper is a proportion of the voltage across the two ends, exactly as in a voltage divider.', 'Volume and tone controls, brightness dimmers, sensor calibration trimmers, analog joystick axes, user input for microcontroller projects via an ADC pin.', 'Simple, tactile, immediate analog adjustment with no extra circuitry required.', 'Mechanical wear over repeated use, susceptible to dust and contact noise, less precise than a digital potentiometer.', NULL, NULL, NULL, '{"Resistance": "1kohm-1Mohm common", "Taper": "Linear or Logarithmic", "Rotation": "270 deg typical", "Power Rating": "0.2W-0.5W", "Package": "Panel mount / PCB"}'::jsonb, '{"potentiometer","variable resistor","analog input","passive"}', 'beginner')
