insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('smd-resistor-0805', 'SMD Resistor (0805)', 'Resistors', 'Yageo', 'Surface-mount chip resistor in the compact 0805 package for dense PCB layouts.', 'The 0805 chip resistor is a ceramic substrate with a resistive film sandwiched between solder-terminated end caps, sized at 2.0mm x 1.25mm. It is one of the most common passive package sizes used on modern production PCBs.', 'Functions identically to any fixed resistor: the printed resistive film sets a defined path for current, but its tiny surface-mount form factor removes leads entirely, letting it be reflow-soldered directly onto pads.', 'Dense consumer electronics PCBs, pull-up/pull-down networks on microcontroller boards, LED current limiting on compact modules.', 'Very small footprint, low parasitic inductance, cheap in bulk reels, ideal for automated pick-and-place assembly.', 'Hard to hand-solder and desolder without practice, difficult to read printed value codes without magnification.', NULL, NULL, NULL, '{"Package Size": "2.0mm x 1.25mm (0805)", "Resistance Range": "0ohm-10Mohm", "Tolerance": "+/-1% / +/-5%", "Power Rating": "0.125W", "Mounting": "SMD"}'::jsonb, '{"resistor","smd","surface mount","passive"}', 'intermediate')
