insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('trimmer-potentiometer', 'Trimmer Potentiometer', 'Resistors', 'Bourns', 'Small screwdriver-adjustable variable resistor intended for one-time or infrequent calibration.', 'A trimmer (or trimpot) is a miniature potentiometer meant to be set once during calibration and then left alone, rather than adjusted by an end user. It is turned with a small screwdriver rather than a knob.', 'Identical operating principle to a full-size potentiometer: a wiper contact slides along a resistive element as an internal screw mechanism is turned, producing an adjustable voltage divider or variable series resistance.', 'Calibrating sensor reference voltages, setting LED brightness or contrast on LCD modules, fine-tuning oscillator or timer circuits.', 'Very low cost, compact PCB footprint, precise multi-turn versions available for fine adjustment.', 'Not intended for frequent adjustment, wiper contact can wear out or drift with vibration over time.', NULL, NULL, 'https://www.bourns.com/docs/Product-Datasheets/3362.pdf', '{"Resistance": "100ohm-1Mohm", "Turns": "Single-turn or 25-turn", "Power Rating": "0.25W", "Package": "PCB mount"}'::jsonb, '{"trimmer","potentiometer","calibration","passive"}', 'beginner')
