insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ceramic-capacitor', 'Ceramic Capacitor', 'Capacitors', 'Murata', 'Non-polarized capacitor using a ceramic dielectric, the most common decoupling capacitor in electronics.', 'Ceramic capacitors use a ceramic material as the dielectric between two conductive plates, giving a small, cheap, non-polarized component. Multi-layer ceramic capacitors (MLCCs) stack many thin layers to reach useful capacitance in a tiny package.', 'Two conductive plates separated by the ceramic dielectric store charge when a voltage is applied; the high permittivity of the ceramic lets a small physical size store meaningful capacitance, and because the dielectric is symmetric the part has no polarity.', 'Bypass and decoupling capacitors next to IC power pins, high-frequency filtering, timing circuits, RF coupling.', 'Cheap, non-polarized so it can be inserted either way, very low equivalent series resistance, good high-frequency response.', 'Capacitance can drop significantly under DC bias voltage depending on dielectric class, some types are microphonic.', NULL, NULL, NULL, '{"Capacitance Range": "1pF-100uF", "Voltage Rating": "16V-100V common", "Dielectric": "X7R / C0G / Y5V", "Package": "THT disc or SMD"}'::jsonb, '{"capacitor","passive","ceramic","decoupling"}', 'beginner')
