insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('electrolytic-capacitor', 'Electrolytic Capacitor', 'Capacitors', 'Nichicon', 'Polarized capacitor offering high capacitance in a compact cylindrical can, used for bulk filtering.', 'Electrolytic capacitors use an oxide layer on an etched aluminum anode as the dielectric together with a liquid or gel electrolyte, allowing very high capacitance values in a relatively small volume compared to other capacitor types.', 'An anodized aluminum foil forms an extremely thin oxide dielectric; the electrolyte acts as the effective cathode, and the large surface area of the etched foil combined with the thin oxide layer produces high capacitance per unit volume.', 'Power supply smoothing and bulk filtering, audio coupling, energy storage on motor driver boards, decoupling near voltage regulators.', 'High capacitance-per-volume and per-cost ratio, well suited to bulk energy storage and ripple filtering.', 'Polarized so reverse voltage can destroy or rupture the part, dries out and loses capacitance over years of service, higher ESR than ceramics.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Electrolytic capacitors-P1090328.JPG', NULL, NULL, '{"Capacitance Range": "1uF-10,000uF", "Voltage Rating": "6.3V-450V", "Polarized": "Yes", "Package": "Radial THT can"}'::jsonb, '{"capacitor","passive","electrolytic","filtering","polarized"}', 'beginner')
