insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('tantalum-capacitor', 'Tantalum Capacitor', 'Capacitors', 'KEMET', 'Polarized capacitor using a tantalum pellet anode for stable capacitance in a small package.', 'Tantalum capacitors use a sintered pellet of porous tantalum metal as the anode, covered by a tantalum pentoxide dielectric layer and a manganese dioxide or conductive polymer cathode, giving stable capacitance in a much smaller case than an equivalent aluminum electrolytic.', 'The porous tantalum pellet has enormous internal surface area, and the extremely thin tantalum pentoxide oxide layer that forms on it acts as the dielectric, so a large capacitance is packed into a very small volume.', 'Space-constrained analog and power circuits, mobile device power filtering, decoupling in RF and precision analog boards.', 'High capacitance density, stable capacitance over temperature and voltage, low leakage current.', 'Can fail short and combust if reverse-biased or over-voltaged, more expensive than electrolytic and ceramic alternatives.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tantalum capacitor.JPG', NULL, NULL, '{"Capacitance Range": "0.1uF-470uF", "Voltage Rating": "6.3V-50V", "Polarized": "Yes", "Package": "SMD case A-E"}'::jsonb, '{"capacitor","passive","tantalum","polarized"}', 'intermediate')
