insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('film-capacitor', 'Film Capacitor', 'Capacitors', 'WIMA', 'Non-polarized capacitor using a plastic film dielectric, prized for stability and low loss.', 'Film capacitors sandwich a thin plastic film such as polyester or polypropylene between metal electrodes, either as discrete foils or a metallized layer directly on the film. They are known for tight tolerance and long-term stability.', 'The plastic film provides a stable, low-loss dielectric between two conductive layers; because the film properties change very little with temperature or applied voltage, the resulting capacitance stays highly consistent over time.', 'Audio crossover networks, snubber circuits, timing circuits requiring stability, AC line filtering, motor-run capacitors.', 'Excellent long-term stability, low dielectric absorption, self-healing property in metallized versions, non-polarized.', 'Physically larger than ceramic or tantalum for the same capacitance, higher cost for large values.', NULL, NULL, NULL, '{"Capacitance Range": "1nF-10uF", "Voltage Rating": "63V-630V", "Dielectric": "Polyester / Polypropylene", "Package": "Radial THT box"}'::jsonb, '{"capacitor","passive","film","audio"}', 'intermediate')
