insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('supercapacitor', 'Supercapacitor (EDLC)', 'Capacitors', 'Eaton', 'Electric double-layer capacitor storing very large amounts of charge for short-term backup power.', 'Supercapacitors, also called ultracapacitors or EDLCs, store energy electrostatically at the interface between an activated carbon electrode and an electrolyte, achieving capacitance thousands of times higher than conventional capacitors of similar size.', 'Instead of a solid dielectric, charge accumulates in an electric double layer that forms at the electrode-electrolyte interface; the enormous surface area of porous activated carbon electrodes gives the device its extremely high capacitance.', 'Memory backup power, energy harvesting buffer storage, regenerative braking systems, bridging brief power interruptions.', 'Very high capacitance, virtually unlimited charge-discharge cycle life compared to batteries, fast charge and discharge.', 'Lower energy density than batteries, voltage drops linearly as it discharges, higher self-discharge rate.', NULL, NULL, NULL, '{"Capacitance Range": "0.1F-500F", "Voltage Rating": "2.7V-5.5V", "Cycle Life": ">500,000 cycles", "Package": "Radial can"}'::jsonb, '{"capacitor","supercapacitor","energy storage","edlc"}', 'intermediate')
