insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('variable-capacitor', 'Variable / Trimmer Capacitor', 'Capacitors', 'Murata', 'Adjustable capacitor whose capacitance changes as a rotor plate moves relative to a stator plate.', 'A variable capacitor (or trimmer capacitor in its miniature PCB-mount form) lets designers fine-tune capacitance after assembly by rotating a shaft or turning a small screw, changing the overlap or spacing between plates.', 'Capacitance is set by the overlapping area and spacing between a movable rotor plate and a fixed stator plate; rotating the rotor changes the effective plate overlap, which changes the capacitance according to the parallel-plate capacitor relationship.', 'Tuning LC resonant circuits in radio receivers, trimming oscillator frequency, impedance matching networks.', 'Allows precise post-assembly tuning, low loss at radio frequencies, repeatable adjustment.', 'Limited capacitance range, mechanically delicate, largely superseded by varactor diodes in modern designs.', NULL, NULL, NULL, '{"Capacitance Range": "2pF-100pF", "Voltage Rating": "50V-250V", "Type": "Air or ceramic dielectric", "Package": "PCB trimmer"}'::jsonb, '{"capacitor","variable","tuning","rf"}', 'advanced')
