insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('toroidal-inductor', 'Toroidal Inductor', 'Inductors', 'Bourns', 'Coil wound on a donut-shaped ferrite or iron powder core that contains its magnetic field efficiently.', 'A toroidal inductor wraps wire around a ring-shaped (toroid) magnetic core. Because the core forms a closed loop, nearly all the magnetic flux stays inside it, giving high inductance for a given wire length and minimal field leakage into nearby circuitry.', 'Current flowing through the coil generates a magnetic field that is concentrated inside the closed toroidal core, storing energy in that field; the closed-loop geometry gives high coupling efficiency and opposes rapid changes in current, per Faraday''s law of induction.', 'Switch-mode power supply filtering, EMI suppression on power lines, transformer cores, audio crossover chokes.', 'Low electromagnetic interference radiation, high inductance for its size, efficient use of core material.', 'Harder to wind by hand than a bobbin coil, more expensive to manufacture, mounting can be less mechanically robust.', NULL, NULL, NULL, '{"Inductance Range": "1uH-10mH", "Core Material": "Ferrite / Iron Powder", "Current Rating": "0.5A-20A", "Package": "THT toroid"}'::jsonb, '{"inductor","passive","toroid","filter"}', 'intermediate')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
