insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ferrite-bead', 'Ferrite Bead', 'Inductors', 'Murata', 'Small ferrite sleeve placed on a wire or trace to suppress high-frequency noise without blocking DC.', 'A ferrite bead is a passive component that looks like a tiny cylinder or bead threaded onto a wire, or a two-terminal SMD part placed in series on a PCB trace. It presents almost no impedance at DC but significant impedance at high frequency.', 'At low frequency the ferrite material behaves mostly as a small inductor with negligible resistance, but at high frequency the core''s magnetic losses dominate and convert unwanted RF energy into heat, effectively acting as a frequency-dependent resistor that attenuates noise.', 'Suppressing EMI on USB and power cables, filtering switching noise on DC power rails, cleaning up clock lines.', 'Cheap and effective broadband noise suppression, negligible effect on DC signals, easy to retrofit on existing cables.', 'Frequency response is not sharply defined, can saturate and lose effectiveness at high DC bias currents.', NULL, NULL, NULL, '{"Impedance @100MHz": "Common 100ohm-1000ohm", "Current Rating": "0.2A-3A", "Package": "SMD bead or clip-on"}'::jsonb, '{"ferrite bead","inductor","emi","noise suppression"}', 'intermediate')
