insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('power-inductor', 'Power Inductor', 'Inductors', 'Wurth Elektronik', 'Shielded high-current inductor used as the energy-storage element in switching voltage regulators.', 'Power inductors are ruggedized coils, often on a shielded drum or molded core, designed to handle the ampere-level currents seen in buck and boost converters without saturating the core or overheating the winding.', 'During each switching cycle the inductor stores energy in its magnetic field while current ramps up through it, then releases that energy to the output as the switch turns off; this repeated charge-discharge cycle smooths the pulsed input into a steady output voltage.', 'Buck and boost converter energy storage, point-of-load power supplies on microcontroller boards, LED driver circuits.', 'High current handling and saturation current rating, low DC resistance for high efficiency, compact shielded packages available.', 'Can produce audible coil whine under certain load conditions, saturating the core causes efficiency to collapse suddenly.', NULL, NULL, NULL, '{"Inductance Range": "1uH-100uH", "Saturation Current": "1A-10A", "DCR": "10mohm-500mohm", "Package": "SMD shielded"}'::jsonb, '{"inductor","power","dc-dc","smps"}', 'advanced')
