insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('rectifier-diode-1n4007', 'Rectifier Diode (1N4007)', 'Diodes', 'ON Semiconductor', 'General-purpose 1A silicon rectifier diode rated to block up to 1000V in the reverse direction.', 'The 1N4007 is the highest-voltage member of the ubiquitous 1N400x family of silicon rectifier diodes, packaged in the axial DO-41 case. It converts alternating current to pulsating direct current by only allowing current to flow in one direction.', 'A P-N junction only conducts significant current when forward biased above roughly 0.7V; when reverse biased it blocks current up to its rated breakdown voltage, so an AC waveform applied across the diode is chopped into a one-directional pulsed output.', 'AC to DC rectification in linear power supplies, reverse-polarity protection, flyback protection across relay coils.', 'Very cheap, widely available, high reverse voltage rating, simple two-terminal operation.', 'Relatively slow switching speed unsuitable for high-frequency circuits, forward voltage drop wastes some power as heat.', NULL, NULL, 'https://www.onsemi.com/pdf/datasheet/1n4001-d.pdf', '{"Forward Current": "1A", "Reverse Voltage": "1000V", "Forward Voltage": "1.1V typ", "Package": "DO-41 axial"}'::jsonb, '{"diode","rectifier","power","1n4007"}', 'beginner')
