insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('schottky-diode-1n5819', 'Schottky Diode (1N5819)', 'Diodes', 'Vishay', 'Metal-semiconductor junction diode with a very low forward voltage drop and fast switching.', 'Schottky diodes form a junction between a metal and an N-type semiconductor rather than a P-N junction, giving a much lower forward voltage drop and virtually no reverse recovery time compared to standard silicon diodes.', 'Because the metal-semiconductor barrier requires far less energy to overcome than a P-N junction, current begins flowing at a lower forward voltage; the absence of minority-carrier charge storage also lets the diode switch off almost instantly when reverse biased.', 'Switching power supply rectification, reverse polarity protection where voltage drop matters, solar panel bypass diodes, RF detectors.', 'Low forward voltage drop reduces power loss, very fast switching speed, low reverse recovery charge.', 'Higher reverse leakage current than standard diodes, lower reverse voltage ratings, more sensitive to reverse breakdown.', NULL, NULL, 'https://www.vishay.com/docs/88525/1n5817.pdf', '{"Forward Current": "1A", "Reverse Voltage": "40V", "Forward Voltage": "0.45V typ", "Package": "DO-41 axial"}'::jsonb, '{"diode","schottky","fast switching","low drop"}', 'intermediate')
