insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('zener-diode', 'Zener Diode', 'Diodes', 'ON Semiconductor', 'Diode designed to operate in controlled reverse breakdown, holding a fixed voltage across itself.', 'Zener diodes are engineered to break down at a precise, repeatable reverse voltage without being destroyed, as long as current is limited externally. This makes them the simplest way to create a fixed voltage reference in a circuit.', 'Beyond a specific reverse voltage the diode''s heavily doped junction enters Zener or avalanche breakdown, conducting current while clamping the voltage across the device to a nearly constant value regardless of further increases in current.', 'Simple voltage reference and regulation circuits, overvoltage protection clamps, shunt regulators, waveform clipping.', 'Cheap and simple way to create a fixed reference voltage, no active circuitry required, wide range of standard voltages.', 'Regulation is imprecise compared to an IC regulator, wastes power as heat, voltage shifts with temperature and current.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Zener Diode.JPG', NULL, NULL, '{"Zener Voltage": "2.4V-100V range", "Power Rating": "0.5W-1.3W", "Tolerance": "+/-5%", "Package": "DO-41 axial"}'::jsonb, '{"diode","zener","voltage reference","clamp"}', 'intermediate')
