insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('switching-diode-1n4148', 'Switching Diode (1N4148)', 'Diodes', 'Vishay', 'Small-signal silicon diode optimized for fast switching in digital and logic-level circuits.', 'The 1N4148 is a small glass-encapsulated diode built for signal-level work rather than power rectification. Its low junction capacitance lets it switch on and off in nanoseconds, making it the default choice for logic-level diode duties.', 'Like any P-N junction diode it conducts in the forward direction once bias exceeds roughly 0.7V, but its small die size gives it low junction capacitance and low stored charge, so it can turn off far faster than a power rectifier of similar current rating.', 'Signal clamping and clipping, logic gate protection, diode-based AND/OR logic, RF and switching circuit steering.', 'Extremely fast switching, low cost, small package, low forward voltage drop for a silicon diode.', 'Very low current rating unsuitable for power applications, fragile glass DO-35 package can crack if leads are bent close to the body.', NULL, NULL, 'https://www.vishay.com/docs/85622/1n4148.pdf', '{"Forward Current": "200mA", "Reverse Voltage": "100V", "Reverse Recovery": "4ns", "Package": "DO-35 glass axial"}'::jsonb, '{"diode","switching","signal","logic"}', 'beginner')
