insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('tvs-diode', 'TVS Diode', 'Diodes', 'Littelfuse', 'Transient voltage suppressor diode that clamps voltage spikes to protect sensitive downstream circuitry.', 'A transient voltage suppression (TVS) diode is built like an oversized, very fast Zener diode. It sits idle under normal operating voltage and only conducts heavily during a brief overvoltage transient, absorbing the energy and clamping the spike.', 'Under normal voltage the TVS diode presents extremely high impedance and draws negligible current; once a transient pushes the voltage past its breakdown threshold it snaps into avalanche conduction within picoseconds, shunting the surge current and clamping the voltage at the load.', 'ESD protection on USB and data lines, lightning and surge protection on power inputs, automotive load dump protection.', 'Extremely fast response time, can absorb repeated transient events, protects downstream ICs from destructive spikes.', 'Adds parasitic capacitance that can affect high-speed signal lines, must be correctly sized or it will not survive the energy of large surges.', NULL, NULL, NULL, '{"Breakdown Voltage": "5V-58V common", "Peak Pulse Power": "400W-1500W", "Response Time": "<1ns", "Package": "SMB / DO-214"}'::jsonb, '{"diode","tvs","esd protection","surge"}', 'advanced')
