insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('led-5mm', 'Standard LED (5mm)', 'LEDs', 'Kingbright', 'Classic through-hole light-emitting diode used as an indicator in nearly every hobby project.', 'The 5mm LED is the archetypal indicator light: a small semiconductor die inside a clear or diffused epoxy dome, with a longer anode lead and a flat-sided cathode for polarity identification.', 'When forward biased above its threshold voltage, electrons and holes recombine at the P-N junction and release energy as photons; the semiconductor material used for the junction determines the emitted wavelength and therefore the perceived color.', 'Power and status indicators, blinking lights on prototyping boards, simple light sources in educational circuits.', 'Very cheap, low power consumption, long lifespan, instant on with no warm-up delay.', 'Requires a current-limiting resistor to avoid burnout, brightness and color vary between production batches.', NULL, NULL, NULL, '{"Forward Voltage": "1.8V-3.3V", "Forward Current": "20mA typical", "Viewing Angle": "20-40 deg", "Package": "5mm THT dome"}'::jsonb, '{"led","indicator","optoelectronic","diode"}', 'beginner')
