insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('rgb-led', 'RGB LED', 'LEDs', 'Kingbright', 'Single package combining red, green, and blue LED dies to produce a wide range of mixed colors.', 'An RGB LED houses three independent LED dies in one package, each with its own cathode or anode lead in the common-cathode or common-anode configuration, letting a controller mix the three colors additively to create nearly any hue.', 'Each of the three internal LED dies emits its own primary color when driven; the human eye blends closely spaced red, green, and blue light sources into a single perceived color, so varying the relative brightness of each die via PWM produces the full visible color range.', 'Mood and status lighting, color-changing indicators, simple ambient lighting projects, backlighting for enclosures.', 'Wide color range from one component, compact, easily controlled with PWM on microcontroller GPIO pins.', 'Requires three current-limiting resistors or a driver IC, forward voltages differ between colors complicating design.', NULL, NULL, NULL, '{"Forward Voltage": "1.8V-3.4V (varies by color)", "Forward Current": "20mA per channel", "Type": "Common cathode/anode", "Package": "5mm or SMD"}'::jsonb, '{"led","rgb","color","optoelectronic"}', 'intermediate')
