insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ir-led', 'Infrared LED', 'LEDs', 'Vishay', 'LED emitting invisible infrared light, used for remote controls and proximity sensing.', 'Infrared LEDs are built from semiconductor materials with a narrower bandgap than visible LEDs, emitting light in the near-infrared range around 850-950nm that is invisible to the human eye but easily detected by photodiodes and phototransistors.', 'Just like a visible LED, forward current causes electron-hole recombination at the junction, but the gallium arsenide based semiconductor used has a bandgap energy that corresponds to an infrared rather than visible wavelength photon.', 'TV and appliance remote controls, IR proximity and obstacle sensors, optical isolation circuits, security beam sensors.', 'Invisible to the human eye avoiding visual distraction, efficient at converting current to IR output, inexpensive.', 'Cannot be visually verified as working without a camera (most phone cameras can see IR), susceptible to ambient IR interference from sunlight.', NULL, NULL, NULL, '{"Wavelength": "850nm-950nm", "Forward Voltage": "1.2V-1.6V", "Forward Current": "20mA-100mA", "Package": "5mm THT"}'::jsonb, '{"led","infrared","ir","optoelectronic"}', 'beginner')
