insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ws2812b-led', 'WS2812B Addressable LED', 'LEDs', 'Worldsemi', 'RGB LED with an integrated driver chip that lets thousands be chained and individually controlled from one data pin.', 'The WS2812B combines an RGB LED die with a tiny driver IC in a single 5050 SMD package. Each LED receives, uses, and re-transmits a serial data stream, so long strips or matrices can be controlled from a single microcontroller pin.', 'A precisely timed single-wire serial protocol carries 24 bits of color data (8 bits each for red, green, and blue) to the first LED; the internal driver latches its own 24 bits and passes the remainder of the stream downstream to the next LED in the chain, repeating along the strip.', 'Addressable LED strips and matrices, ambient lighting displays, wearable electronics, art installations and signage.', 'Individually addressable with only one data wire per chain, integrated driver removes need for external transistors, vivid full-color output.', 'Strict timing requirements for the data signal, whole downstream chain fails if one LED dies, can draw significant current at full brightness.', NULL, NULL, 'https://cdn-shop.adafruit.com/datasheets/WS2812B.pdf', '{"Supply Voltage": "3.5V-5.3V", "Current per LED": "up to 60mA", "Protocol": "Single-wire NZR", "Package": "5050 SMD"}'::jsonb, '{"led","addressable","ws2812","rgb","smart led"}', 'intermediate')
