insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('npn-transistor-2n2222', 'NPN Transistor (2N2222)', 'Transistors', 'ON Semiconductor', 'General-purpose NPN bipolar junction transistor for switching and amplification in low-power circuits.', 'The 2N2222 is one of the most widely used NPN transistors in electronics education and hobby work, packaged in the compact TO-92 case. It can switch small loads or amplify small signals in a huge range of low-voltage circuits.', 'A small current flowing into the base terminal controls a much larger current flowing from collector to emitter; below the base current threshold the transistor is off, above it the transistor saturates and behaves like a closed switch, with the region between usable for linear amplification.', 'Driving relays and small motors from a microcontroller pin, audio signal amplification, simple logic-level switching circuits.', 'Cheap and widely available, easy to use for both switching and amplification, well documented with predictable behavior.', 'Limited current and power handling compared to power transistors, requires a base resistor to avoid damage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Transistorer (cropped).jpg', NULL, 'https://www.onsemi.com/pdf/datasheet/p2n2222a-d.pdf', '{"Type": "NPN BJT", "Collector Current": "800mA max", "Collector-Emitter Voltage": "40V max", "Package": "TO-92", "hFE": "100-300 typical"}'::jsonb, '{"transistor","npn","bjt","switching","amplifier"}', 'beginner')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
