insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('pnp-transistor-2n2907', 'PNP Transistor (2N2907)', 'Transistors', 'ON Semiconductor', 'Complementary PNP counterpart to the 2N2222, used for high-side switching and complementary amplifier stages.', 'The 2N2907 is a general-purpose PNP bipolar junction transistor, electrically the mirror image of the NPN 2N2222. It conducts when the base is pulled low relative to the emitter, making it ideal for high-side switching where the load connects to ground and the transistor connects to the positive supply.', 'Current flows from emitter to collector when the base is held at a lower potential than the emitter by more than about 0.7V, allowing a small base current to control a larger emitter-to-collector current, the PNP mirror of standard NPN operation.', 'High-side load switching, complementary push-pull amplifier output stages, level-shifting circuits.', 'Enables high-side switching that NPN transistors cannot do simply, pin-compatible complement to popular NPN parts.', 'Generally lower current gain and slower switching than equivalent NPN parts, less intuitive for beginners than NPN.', NULL, NULL, 'https://www.onsemi.com/pdf/datasheet/p2n2907a-d.pdf', '{"Type": "PNP BJT", "Collector Current": "600mA max", "Collector-Emitter Voltage": "-60V max", "Package": "TO-92", "hFE": "100-300 typical"}'::jsonb, '{"transistor","pnp","bjt","switching"}', 'intermediate')
