insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('darlington-transistor-tip120', 'Darlington Transistor (TIP120)', 'Transistors', 'ON Semiconductor', 'Power NPN Darlington pair in a single TO-220 package, delivering very high current gain for driving heavy loads.', 'The TIP120 packages two bipolar transistors internally connected as a Darlington pair, multiplying their individual current gains together. This lets a microcontroller pin, through only a small base current, switch several amps of load current.', 'The first transistor amplifies the small input base current and feeds its emitter current into the base of the second transistor, so the overall current gain is approximately the product of the two individual transistor gains, letting a tiny drive current control a large load current.', 'Driving DC motors, solenoids, and relay coils directly from a microcontroller pin, high-current switching in robotics projects.', 'Very high current gain reduces required base drive, rugged TO-220 package handles several amps, simple to use.', 'Higher saturation voltage than a MOSFET so it dissipates more heat, slower switching speed limits PWM frequency.', NULL, NULL, 'https://www.onsemi.com/pdf/datasheet/tip120-d.pdf', '{"Type": "NPN Darlington", "Collector Current": "5A max", "Collector-Emitter Voltage": "60V max", "Package": "TO-220", "hFE": "1000 min"}'::jsonb, '{"transistor","darlington","power","motor driver"}', 'intermediate')
