insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('bc547-transistor', 'General Purpose NPN Transistor (BC547)', 'Transistors', 'STMicroelectronics', 'Low-noise general-purpose NPN transistor extremely common in European hobby and educational kits.', 'The BC547 is a small-signal NPN transistor in the same TO-92 family as the 2N2222, favored in many textbook circuits and kits outside North America. It offers modest current handling with good gain linearity for small-signal amplification.', 'Operates as a standard bipolar junction transistor: a small base current controls a proportionally larger collector current, with the ratio set by the device''s current gain (hFE), enabling both switching and linear amplifier applications.', 'Audio preamplifier stages, simple logic-level switches, sensor signal buffering, hobby electronics kits and textbooks.', 'Low noise suited to small-signal audio work, widely stocked and inexpensive, predictable well-documented behavior.', 'Low current and power rating limits it to signal-level work, not suitable for driving motors or heavy loads directly.', NULL, NULL, 'https://www.st.com/resource/en/datasheet/bc547.pdf', '{"Type": "NPN BJT", "Collector Current": "100mA max", "Collector-Emitter Voltage": "45V max", "Package": "TO-92", "hFE": "110-800"}'::jsonb, '{"transistor","npn","bjt","audio","general purpose"}', 'beginner')
