insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('mosfet-irf540n', 'N-Channel Power MOSFET (IRF540N)', 'MOSFETs', 'Infineon', 'High-current N-channel power MOSFET commonly used to switch motors and heavy DC loads.', 'The IRF540N is a widely used TO-220 power MOSFET capable of switching over 20A. It is a staple in motor controllers, PWM dimmers, and DIY power electronics because of its low on-resistance and rugged current handling.', 'A voltage applied to the insulated gate creates an electric field that forms a conductive channel between the drain and source terminals; because the gate is insulated by a thin oxide layer, it draws essentially no continuous current, needing only enough charge to switch the gate capacitance.', 'DC motor speed control, high-current PWM switching, battery load switching, DIY power supply and driver circuits.', 'Very low on-resistance minimizes heat generation, high current and voltage rating, virtually no gate drive current at DC.', 'Needs a proper gate driver for fast, efficient switching at high frequency, standard threshold voltage may not fully turn on from 3.3V logic.', NULL, NULL, 'https://www.infineon.com/dgdl/irf540n.pdf', '{"Type": "N-Channel MOSFET", "Drain Current": "33A", "Drain-Source Voltage": "100V", "RDS(on)": "44mohm", "Package": "TO-220"}'::jsonb, '{"mosfet","power","switching","motor driver"}', 'intermediate')
