insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('mosfet-irf9540', 'P-Channel Power MOSFET (IRF9540)', 'MOSFETs', 'Infineon', 'P-channel complement to common N-channel power MOSFETs, used for high-side load switching.', 'The IRF9540 conducts when its gate is pulled negative relative to the source, making it well suited for high-side switching where the source connects to the positive rail. It is the P-channel partner commonly paired with N-channel devices in H-bridge designs.', 'Applying a negative gate-to-source voltage attracts holes to form a conductive P-type channel between source and drain; once the channel forms, current can flow from source to drain with very low resistance, mirroring N-channel operation with opposite polarity.', 'High-side load and battery switching, H-bridge motor driver upper switches, reverse-polarity protection circuits.', 'Simplifies high-side switching compared to using an N-channel device with a charge pump, straightforward gate drive referenced to the supply rail.', 'Higher on-resistance than an equivalent N-channel part, generally lower current ratings and higher cost.', NULL, NULL, 'https://www.infineon.com/dgdl/irf9540n.pdf', '{"Type": "P-Channel MOSFET", "Drain Current": "-19A", "Drain-Source Voltage": "-100V", "RDS(on)": "117mohm", "Package": "TO-220"}'::jsonb, '{"mosfet","p-channel","power","high-side switch"}', 'advanced')
