insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('mosfet-irlz44n', 'Logic-Level N-Channel MOSFET (IRLZ44N)', 'MOSFETs', 'Infineon', 'Power MOSFET with a low gate threshold voltage, allowing direct switching from 3.3V or 5V logic pins.', 'Unlike standard power MOSFETs that need 10V or more on the gate to fully turn on, the IRLZ44N is a logic-level device that reaches low on-resistance with only a few volts of gate drive, making it directly compatible with microcontroller GPIO pins.', 'The device is fabricated with a lower gate threshold voltage than standard MOSFETs, so the channel forms fully and on-resistance drops to its rated minimum even when driven from a 5V or 3.3V logic-level gate signal rather than a full 10V gate driver.', 'PWM dimming and motor control driven directly from Arduino or ESP32 GPIO pins, MOSFET-based load switches in battery-powered projects.', 'Can be switched fully on directly from microcontroller logic without a separate gate driver, low on-resistance, widely used in hobby projects.', 'Still benefits from a gate resistor and sometimes a pull-down to avoid floating-gate issues, can overheat if PWM switching losses are ignored at high frequency.', NULL, NULL, 'https://www.infineon.com/dgdl/irlz44n.pdf', '{"Type": "N-Channel Logic-Level MOSFET", "Drain Current": "47A", "Drain-Source Voltage": "55V", "RDS(on)": "22mohm @ 5V Vgs", "Package": "TO-220"}'::jsonb, '{"mosfet","logic-level","arduino","switching"}', 'intermediate')
