insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('mosfet-2n7000', 'Small-Signal MOSFET (2N7000)', 'MOSFETs', 'ON Semiconductor', 'Low-power N-channel MOSFET in a TO-92 package, used for small switching and level-shifting tasks.', 'The 2N7000 is a small-signal enhancement-mode MOSFET that behaves like a miniature version of a power MOSFET, useful anywhere a low-current electronic switch or level shifter is needed without the bulk of a TO-220 device.', 'A positive gate-to-source voltage above the threshold forms a conductive N-type channel between drain and source; because the MOSFET draws virtually no static gate current, it can be driven directly from a logic output with only a small series resistor.', 'Bidirectional logic-level shifting between 3.3V and 5V systems, low-current load switching, driving small LEDs or opto-isolators.', 'Tiny size, essentially zero static gate current draw, simple to use for logic-level switching tasks.', 'Limited to small currents unsuitable for motors or heavy loads, on-resistance is higher than power MOSFETs.', NULL, NULL, 'https://www.onsemi.com/pdf/datasheet/2n7000-d.pdf', '{"Type": "N-Channel MOSFET", "Drain Current": "200mA", "Drain-Source Voltage": "60V", "RDS(on)": "1.2ohm-5ohm", "Package": "TO-92"}'::jsonb, '{"mosfet","small signal","level shifter","logic"}', 'intermediate')
