insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lm7805-regulator', 'LM7805 Linear Voltage Regulator', 'Voltage Regulators', 'Texas Instruments', 'Fixed 5V, 1A linear regulator in a TO-220 package, one of the most recognizable ICs in electronics.', 'The 7805 is a three-terminal linear regulator that produces a stable 5V output from an unregulated input voltage a few volts higher. Its simplicity, just input, ground, and output pins, has made it a staple of countless power supply designs.', 'An internal reference and error amplifier continuously adjust a series pass transistor so the output stays fixed at 5V; any excess voltage between the input and the regulated output is dissipated as heat across the pass transistor, so efficiency drops as the input-output voltage difference grows.', 'Powering 5V logic circuits from a higher-voltage battery or wall adapter, simple bench power supplies, Arduino shield regulation.', 'Extremely simple to use with just two capacitors, built-in thermal and short-circuit protection, low cost.', 'Linear regulation wastes energy as heat, requires a heatsink under load, needs at least 2V of headroom above 5V to regulate properly.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/lm7805.pdf', '{"Output Voltage": "5V fixed", "Output Current": "1A max", "Dropout Voltage": "~2V", "Package": "TO-220"}'::jsonb, '{"voltage regulator","linear","5v","power"}', 'beginner')
