insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lm317-regulator', 'LM317 Adjustable Voltage Regulator', 'Voltage Regulators', 'Texas Instruments', 'Three-terminal linear regulator whose output voltage is set by two external resistors, from 1.25V up to 37V.', 'Unlike fixed regulators such as the 7805, the LM317 lets the designer program any output voltage in its range using a simple resistor divider, making it a flexible building block for bench supplies and custom voltage rails.', 'The regulator holds a constant 1.25V reference between its output and adjust pins; feeding that reference through an external resistor divider sets a proportional output voltage, following the formula Vout = 1.25V x (1 + R2/R1).', 'Adjustable bench power supplies, battery charger circuits, custom voltage rails for prototyping, LED driver current source configuration.', 'Fully adjustable output with just two resistors, excellent line and load regulation, built-in current limiting and thermal shutdown.', 'Like all linear regulators it wastes power as heat at high current or large voltage drop, needs a minimum load current to regulate well.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/lm317.pdf', '{"Output Voltage": "1.25V-37V adjustable", "Output Current": "1.5A max", "Dropout Voltage": "~2V", "Package": "TO-220"}'::jsonb, '{"voltage regulator","adjustable","linear","power"}', 'intermediate')
