insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ams1117-regulator', 'AMS1117 3.3V LDO Regulator', 'Voltage Regulators', 'Advanced Monolithic Systems', 'Low-dropout linear regulator that converts 5V to a clean 3.3V rail, found on nearly every dev board.', 'The AMS1117-3.3 is a small SOT-223 low-dropout regulator that only needs about 1V of headroom to maintain regulation, making it the go-to part for generating a 3.3V logic rail from a 5V USB supply on countless microcontroller and sensor boards.', 'A low-dropout design uses a PMOS or PNP pass device that can stay in its linear region with only a small voltage difference between input and output, so the regulator maintains a steady 3.3V output even when the input sags close to that value.', 'Generating a 3.3V logic rail from 5V USB power on ESP8266, ESP32, and sensor breakout boards, general low-power 3.3V regulation.', 'Low dropout voltage suits USB-powered designs, tiny SOT-223 footprint, cheap and available in fixed or adjustable versions.', 'Still a linear regulator so efficiency suffers under large voltage drops, limited output current compared to switching regulators.', NULL, NULL, 'https://www.advanced-monolithic.com/pdf/ds1117.pdf', '{"Output Voltage": "3.3V fixed", "Output Current": "1A max", "Dropout Voltage": "~1.1V", "Package": "SOT-223"}'::jsonb, '{"voltage regulator","ldo","3.3v","power"}', 'beginner')
