insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lm2596-buck-module', 'LM2596 Buck Converter Module', 'Voltage Regulators', 'Texas Instruments', 'Adjustable switching step-down regulator module that efficiently converts a higher DC voltage down to a lower one.', 'This small breakout board wraps the LM2596 switching regulator IC with its inductor, diode, and adjustment potentiometer, giving a plug-and-play buck converter that steps down voltages like 12V or 24V to a lower rail such as 5V with much higher efficiency than a linear regulator.', 'The IC rapidly switches an internal transistor on and off at around 150kHz, storing energy in an inductor during the on phase and releasing it to the output during the off phase; the ratio of on-time to switching period sets the average output voltage, giving high efficiency because the switch itself dissipates little power.', 'Stepping down car battery voltage to power 5V electronics, efficient point-of-load conversion in battery-powered projects, replacing hot linear regulators in higher-power designs.', 'Much higher efficiency than a linear regulator, especially with a large input-output voltage difference, handles several amps without a heatsink.', 'Switching noise requires careful layout and filtering, bulkier than a simple three-pin linear regulator, output ripple is higher than linear regulation.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/lm2596.pdf', '{"Input Voltage": "4.5V-40V", "Output Voltage": "1.25V-37V adjustable", "Output Current": "3A max", "Switching Frequency": "150kHz"}'::jsonb, '{"voltage regulator","buck converter","switching","dc-dc"}', 'intermediate')
