insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lm358-opamp', 'LM358 Dual Operational Amplifier', 'Operational Amplifiers', 'Texas Instruments', 'Low-power dual op-amp that runs from a single supply, one of the most common general-purpose op-amps.', 'The LM358 packs two independent operational amplifiers in one 8-pin DIP or SOIC package and is unusual among classic op-amps in that it works well from a single positive supply rather than requiring a split plus and minus rail.', 'An operational amplifier drives its output to force the voltage difference between its two inputs toward zero, using high open-loop gain and external feedback components to set a precise, predictable closed-loop gain or comparison behavior.', 'Sensor signal conditioning and amplification, simple analog comparators, active filters, audio preamplifier stages.', 'Operates from a single 3V-32V supply simplifying battery-powered designs, low quiescent current, two amplifiers per package.', 'Crossover distortion near ground limits its use in high-fidelity audio, relatively slow slew rate compared to modern op-amps.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/lm358.pdf', '{"Channels": "2", "Supply Voltage": "3V-32V single supply", "Slew Rate": "0.3V/us", "Package": "DIP-8 / SOIC-8"}'::jsonb, '{"op-amp","analog","amplifier","ic"}', 'intermediate')
