insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lm741-opamp', 'LM741 Operational Amplifier', 'Operational Amplifiers', 'Texas Instruments', 'Classic single op-amp used for decades in analog design education and general-purpose amplification.', 'The 741 was one of the first widely produced monolithic operational amplifiers and remains a textbook standard for teaching analog circuit design, even though newer parts outperform it in nearly every specification.', 'Internally the 741 uses a differential input stage feeding a high-gain voltage amplifier stage and a class-AB output stage; external feedback resistors set the exact closed-loop gain, while its internal frequency compensation keeps the amplifier stable across a wide range of gains.', 'Educational analog circuit labs, basic signal amplification, active filter and integrator/differentiator circuits, audio mixing stages.', 'Extremely well documented with decades of reference designs, internally frequency-compensated so it is stable without extra components.', 'Slow slew rate and limited bandwidth by modern standards, higher offset voltage and noise than contemporary op-amps.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/lm741.pdf', '{"Channels": "1", "Supply Voltage": "+/-5V to +/-18V dual supply", "Slew Rate": "0.5V/us", "Package": "DIP-8"}'::jsonb, '{"op-amp","analog","classic","amplifier"}', 'intermediate')
