insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('tl072-opamp', 'TL072 Low-Noise Dual JFET Op-Amp', 'Operational Amplifiers', 'Texas Instruments', 'Dual JFET-input operational amplifier prized in audio circuits for its low noise and high input impedance.', 'The TL072 uses JFET transistors at its input stage instead of bipolar transistors, giving extremely high input impedance and very low input bias current, characteristics that make it a favorite in audio preamps, effects pedals, and precision analog circuits.', 'JFET input transistors draw orders of magnitude less input bias current than bipolar transistors, so the amplifier barely loads the source signal; combined with a low-noise design, this lets the TL072 faithfully amplify small audio-frequency signals with minimal added distortion.', 'Guitar pedal and audio preamplifier circuits, active filters for audio processing, buffering high-impedance sensor sources.', 'Very high input impedance and low bias current, low noise floor well suited to audio, decent slew rate.', 'Requires a dual supply for full-range audio swing in most designs, more expensive than basic bipolar op-amps.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/tl072.pdf', '{"Channels": "2", "Supply Voltage": "+/-3.5V to +/-18V", "Slew Rate": "13V/us", "Package": "DIP-8 / SOIC-8"}'::jsonb, '{"op-amp","jfet","audio","low noise"}', 'advanced')
