insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('74hc595-shift-register', '74HC595 Shift Register', 'Logic ICs', 'Texas Instruments', '8-bit serial-in, parallel-out shift register used to add extra digital outputs to a microcontroller.', 'The 74HC595 lets a microcontroller control eight output pins using only three GPIO lines by shifting data in serially and then latching it out in parallel. Multiple chips can be chained to add many more outputs from the same three control lines.', 'Data bits are clocked serially into an internal 8-bit shift register one at a time on the clock pin; once all 8 bits are loaded, pulsing the latch pin copies the shift register contents into a parallel output register, updating all 8 output pins simultaneously without glitching mid-shift.', 'Driving multiple LEDs or seven-segment displays from few microcontroller pins, expanding GPIO for relay banks, LED matrix driving.', 'Expands digital outputs dramatically using only three control pins, chainable for even more outputs, inexpensive.', 'Outputs only, not usable for reading inputs, limited output current per pin requiring buffering for larger loads.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/sn74hc595.pdf', '{"Type": "8-bit SIPO shift register", "Supply Voltage": "2V-6V", "Output Current": "35mA per pin max", "Package": "DIP-16 / SOIC-16"}'::jsonb, '{"shift register","logic ic","gpio expander","digital"}', 'intermediate')
