insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('74hc00-nand-gate', '74HC00 Quad NAND Gate', 'Logic ICs', 'Texas Instruments', 'IC containing four independent 2-input NAND gates, a fundamental building block of digital logic.', 'The 74HC00 packages four separate 2-input NAND gates in one 14-pin chip. Because NAND gates are functionally complete, any other logic function (AND, OR, NOT, XOR) can be built entirely from NAND gates alone.', 'Each gate outputs logic low only when both of its inputs are simultaneously logic high; for any other input combination the output is logic high, implementing the Boolean NAND function in high-speed CMOS logic.', 'Building custom digital logic circuits, oscillator and debounce circuits, teaching Boolean algebra and digital design fundamentals.', 'Fast CMOS switching speed, low power consumption, four gates per package reduces board space.', 'Unused inputs must be tied to a defined level or the chip can behave unpredictably, limited to simple combinational logic compared to a microcontroller.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/sn74hc00.pdf', '{"Gates": "4x 2-input NAND", "Supply Voltage": "2V-6V", "Propagation Delay": "~9ns", "Package": "DIP-14 / SOIC-14"}'::jsonb, '{"logic ic","nand gate","digital logic","cmos"}', 'beginner')
