insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('cd4017-decade-counter', 'CD4017 Decade Counter', 'Logic ICs', 'Texas Instruments', 'CMOS decade counter with 10 sequential outputs, walking a single high signal from one output to the next on each clock pulse.', 'The 4017 is a Johnson decade counter that lights one of ten outputs at a time, advancing to the next output on every rising clock edge, which makes it a popular building block for LED chasers and simple sequencing circuits without needing a microcontroller.', 'Internally a chain of flip-flops implements a Johnson counter, decoded to ten mutually exclusive outputs; each clock pulse advances the active output by one position in sequence, wrapping back to the first output after the tenth, with a carry-out pulse every ten clocks.', 'LED chaser and sequencer circuits, simple frequency division, non-microcontroller step sequencers for music synthesizers.', 'No programming required to sequence outputs, low power CMOS operation, simple to cascade for longer sequences.', 'Limited to sequential/counting logic rather than general computation, fixed 10-step cycle unless reset early.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/cd4017b.pdf', '{"Outputs": "10 decoded + carry", "Supply Voltage": "3V-15V", "Max Clock Frequency": "5MHz typical", "Package": "DIP-16"}'::jsonb, '{"logic ic","counter","cmos","sequencer"}', 'intermediate')
