insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('cd4051-multiplexer', 'CD4051 8-Channel Analog Multiplexer', 'Logic ICs', 'Texas Instruments', 'CMOS analog multiplexer that switches one of eight analog input channels through to a single common pin.', 'The CD4051 acts as an electronically controlled 8-way switch for analog signals, selecting one of eight input/output channels based on a 3-bit binary address, letting a microcontroller read many more analog sensors than it has ADC pins for.', 'Three digital select pins form a 3-bit binary address that closes one internal bidirectional CMOS switch at a time, connecting the chosen channel to the common pin while all other channels remain high-impedance, so signals can flow in either direction through the selected path.', 'Expanding a microcontroller''s analog input count, routing multiple sensors to one ADC channel, audio signal routing.', 'Bidirectional analog switching, expands limited ADC pins significantly, low on-resistance CMOS switches.', 'Switching introduces small additional resistance and settling time, requires careful supply/signal range matching.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/cd4051b.pdf', '{"Channels": "8:1 analog mux/demux", "Supply Voltage": "3V-15V (or dual +/-)", "On Resistance": "~125ohm typical", "Package": "DIP-16"}'::jsonb, '{"logic ic","multiplexer","analog switch","cmos"}', 'advanced')
