insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ne555-timer', 'NE555 Timer IC', 'Timer ICs', 'Texas Instruments', 'The most famous timer chip ever made, used to generate precise pulses, delays, and oscillations.', 'First released in 1971, the 555 timer has been called probably the most popular integrated circuit ever made, with an estimated billion units produced annually. Configured with a handful of resistors and capacitors it can act as a one-shot timer, an astable oscillator, or a pulse-width modulator.', 'Two internal comparators watch the voltage on a timing capacitor against reference thresholds set by an internal resistor ladder; depending on external resistor and capacitor values and wiring (astable, monostable, or bistable configuration), the chip''s output flips high or low at precisely timed intervals as the capacitor charges and discharges.', 'LED blinker and flasher circuits, PWM motor speed control, tone and audio oscillators, debounce and delay timers, pulse generation for other digital logic.', 'Extremely well documented with countless reference circuits, works from a wide supply range, cheap and rugged.', 'Timing accuracy depends on external RC component tolerance, output can glitch on power-up in some configurations, less precise than a crystal-based timer.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/ne555.pdf', '{"Modes": "Astable / Monostable / Bistable", "Supply Voltage": "4.5V-16V", "Output Current": "200mA max", "Package": "DIP-8"}'::jsonb, '{"timer ic","555","oscillator","pwm"}', 'beginner')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
