insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ne556-dual-timer', 'NE556 Dual Timer IC', 'Timer ICs', 'Texas Instruments', 'Dual version of the 555 timer, packing two independent timer circuits in one 14-pin package.', 'The 556 is functionally two 555 timers sharing a single supply and ground pin, saving board space whenever a design needs two independent timing or oscillator stages, such as a two-tone siren or a two-stage delay circuit.', 'Each half operates exactly like an individual 555 timer with its own trigger, threshold, discharge, and output pins, using its own external RC network to set timing, while both halves share only the common power and ground connections.', 'Two-tone alarm and siren circuits, dual independent PWM channels, sequential delay-then-pulse timing chains.', 'Halves the component count versus using two separate 555 chips, identical well-understood timing behavior.', 'More pins to route than a single 555, shared supply pin means both timers must use compatible voltage ranges.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/ne556.pdf', '{"Timers": "2 independent", "Supply Voltage": "4.5V-16V", "Output Current": "200mA max per timer", "Package": "DIP-14"}'::jsonb, '{"timer ic","555","dual timer","oscillator"}', 'intermediate')
on conflict (slug) do update set
