insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('atmega328p', 'ATmega328P Microcontroller', 'Microcontrollers', 'Microchip', '8-bit AVR microcontroller that powers the classic Arduino Uno, beloved for its simplicity and reliability.', 'The ATmega328P is an 8-bit AVR microcontroller with 32KB of flash memory, 2KB of SRAM, and a rich set of peripherals including ADC, PWM, UART, SPI, and I2C, all running at up to 20MHz. It is the chip most people mean when they picture a beginner-friendly microcontroller.', 'A RISC 8-bit CPU core executes most instructions in a single clock cycle, fetching program code from onboard flash memory and manipulating data in SRAM and its register file; onboard peripherals like timers and the ADC run semi-independently, raising interrupts to the CPU when they need attention.', 'Standalone embedded projects, the heart of the Arduino Uno and Nano boards, simple sensor loggers, robotics controllers.', 'Huge ecosystem of libraries and tutorials via the Arduino platform, low power consumption, simple and forgiving for beginners.', 'Limited flash, RAM, and clock speed compared to 32-bit microcontrollers, no built-in wireless connectivity.', NULL, NULL, 'https://ww1.microchip.com/downloads/en/DeviceDoc/Atmel-42735-8-bit-AVR-Microcontroller-ATmega328-328P_Datasheet.pdf', '{"Architecture": "8-bit AVR RISC", "Clock Speed": "up to 20MHz", "Flash": "32KB", "SRAM": "2KB", "Package": "DIP-28 / TQFP-32"}'::jsonb, '{"microcontroller","avr","arduino","8-bit"}', 'intermediate')
