insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('esp32-wroom32', 'ESP32-WROOM-32 Module', 'Microcontrollers', 'Espressif', 'Dual-core Wi-Fi and Bluetooth SoC module that has become the default choice for modern IoT projects.', 'The ESP32-WROOM-32 packages Espressif''s dual-core Xtensa LX6 SoC, integrated Wi-Fi and Bluetooth radios, flash memory, and a PCB antenna into a single shielded module, giving huge processing and wireless capability at a very low cost.', 'Two 32-bit Xtensa CPU cores run application code and can be assigned separate tasks such as networking versus sensor processing; the integrated RF subsystem handles the 2.4GHz Wi-Fi and Bluetooth baseband and protocol stack, freeing the application cores to focus on user logic.', 'IoT sensor nodes reporting over Wi-Fi, home automation controllers, Bluetooth peripherals, robotics with wireless telemetry.', 'Integrated Wi-Fi and Bluetooth eliminate the need for separate radio modules, dual-core processing headroom, very low cost.', 'Higher power consumption than simple 8-bit microcontrollers, 3.3V-only I/O requires level shifting for 5V peripherals.', NULL, NULL, 'https://www.espressif.com/sites/default/files/documentation/esp32-wroom-32_datasheet_en.pdf', '{"CPU": "Dual-core Xtensa LX6 @ 240MHz", "Flash": "4MB typical", "Wireless": "802.11 b/g/n Wi-Fi + Bluetooth 4.2", "Package": "38-pin SMD module"}'::jsonb, '{"microcontroller","esp32","wifi","bluetooth","iot"}', 'intermediate')
