insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('esp8266-esp12f', 'ESP8266 (ESP-12F) Wi-Fi Module', 'Microcontrollers', 'Espressif', 'Low-cost Wi-Fi enabled microcontroller module that helped kick off the affordable IoT hobbyist movement.', 'The ESP8266, in its popular ESP-12F module form, combines a 32-bit Tensilica CPU with a full Wi-Fi radio and TCP/IP stack in a package barely larger than a postage stamp, making internet-connected projects accessible at a fraction of the earlier cost of adding Wi-Fi.', 'A single 32-bit CPU core runs both the user application and, via onboard firmware and SDK, manages the Wi-Fi radio and network stack, communicating over station or access-point mode 802.11 b/g/n to join or host wireless networks.', 'Basic IoT sensor nodes, Wi-Fi controlled relays and smart plugs, low-cost web server projects, NodeMCU-based prototyping.', 'Very cheap for a Wi-Fi capable microcontroller, huge community support and firmware options, small footprint.', 'Single core limits real-time responsiveness while Wi-Fi is active, fewer GPIO pins than the ESP32, only one true analog input.', NULL, NULL, 'https://www.espressif.com/sites/default/files/documentation/0a-esp8266ex_datasheet_en.pdf', '{"CPU": "32-bit Tensilica L106 @ 80/160MHz", "Flash": "External, commonly 4MB", "Wireless": "802.11 b/g/n Wi-Fi", "Package": "16-pin SMD module"}'::jsonb, '{"microcontroller","esp8266","wifi","iot"}', 'intermediate')
