insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('stm32f103c8t6', 'STM32F103C8T6 (Blue Pill)', 'Microcontrollers', 'STMicroelectronics', '32-bit ARM Cortex-M3 microcontroller popularized by the inexpensive Blue Pill development board.', 'The STM32F103C8T6 brings a genuine 32-bit ARM Cortex-M3 core with rich peripherals to hobbyists at a very low price, most famously on the tiny blue Blue Pill board, offering far more performance and peripheral flexibility than 8-bit alternatives.', 'The Cortex-M3 core executes ARM Thumb-2 instructions with a 3-stage pipeline, and its extensive peripheral set (timers, ADCs, USB, CAN, multiple UARTs) connects over internal buses that the CPU can access directly or via DMA to offload data transfers without CPU intervention.', 'More demanding embedded projects needing USB, CAN bus, or multiple simultaneous peripherals, motor control, precision instrumentation.', 'Significant performance jump over 8-bit microcontrollers, rich peripheral set including USB and CAN, low cost.', 'Steeper learning curve than Arduino-style 8-bit chips, many Blue Pill boards ship with counterfeit or marginal-quality flash chips.', NULL, NULL, 'https://www.st.com/resource/en/datasheet/stm32f103c8.pdf', '{"Architecture": "32-bit ARM Cortex-M3", "Clock Speed": "up to 72MHz", "Flash": "64KB", "SRAM": "20KB", "Package": "LQFP-48"}'::jsonb, '{"microcontroller","arm","stm32","32-bit"}', 'advanced')
