insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('pic16f877a', 'PIC16F877A Microcontroller', 'Microcontrollers', 'Microchip', 'Classic 8-bit PIC microcontroller widely used in engineering education and industrial control.', 'The PIC16F877A is a workhorse 8-bit microcontroller from Microchip''s PIC family, offering a balanced mix of flash memory, RAM, ADC channels, and communication peripherals that has made it a staple in university embedded systems courses for decades.', 'A Harvard-architecture CPU fetches instructions from separate flash program memory while reading and writing data memory independently, allowing single-cycle execution for most instructions; onboard modules like the ADC, UART, and timers operate largely independently, interrupting the CPU only when a task completes.', 'University embedded systems coursework, industrial control panels, legacy product designs, standalone sensor and control circuits.', 'Mature, extremely well documented architecture with decades of reference material, generous I/O count, low cost.', 'Dated compared to modern 32-bit options, requires a separate programmer, more complex instruction set quirks than AVR.', NULL, NULL, 'https://ww1.microchip.com/downloads/en/DeviceDoc/39582b.pdf', '{"Architecture": "8-bit PIC RISC", "Clock Speed": "up to 20MHz", "Flash": "8K words (14.3KB)", "SRAM": "368 bytes", "Package": "DIP-40"}'::jsonb, '{"microcontroller","pic","8-bit","education"}', 'advanced')
