insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('arduino-uno-r3', 'Arduino Uno R3', 'Development Boards', 'Arduino', 'The board that launched the modern hobbyist electronics movement, built around the ATmega328P.', 'The Arduino Uno R3 pairs the ATmega328P microcontroller with USB-to-serial programming, a simple 5V I/O header layout, and the enormously popular Arduino IDE and library ecosystem, making it the reference starting point for millions of makers.', 'An onboard USB-to-serial bridge chip lets a computer flash compiled sketches into the ATmega328P''s flash memory over USB; once programmed, the microcontroller runs standalone, reading its digital and analog pins and driving outputs according to the uploaded program''s logic.', 'Beginner electronics education, simple robotics, sensor data logging, prototyping before moving to a custom PCB.', 'Enormous library and tutorial ecosystem, simple 5V-tolerant I/O forgiving of wiring mistakes, robust USB bootloader workflow.', 'No built-in wireless connectivity, limited processing power and memory compared to 32-bit boards, larger and pricier than bare microcontroller modules.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arduino Uno - R3.jpg', NULL, 'https://docs.arduino.cc/resources/datasheets/A000066-datasheet.pdf', '{"Microcontroller": "ATmega328P", "Operating Voltage": "5V", "Digital I/O Pins": "14 (6 PWM)", "Analog Input Pins": "6", "Clock Speed": "16MHz"}'::jsonb, '{"development board","arduino","beginner","atmega328p"}', 'beginner')
