insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('raspberry-pi-4', 'Raspberry Pi 4 Model B', 'Development Boards', 'Raspberry Pi Foundation', 'Credit-card-sized single-board computer capable of running a full Linux desktop, not just embedded firmware.', 'The Raspberry Pi 4 Model B is a complete computer on a single board, with a quad-core 64-bit CPU, up to 8GB of RAM, dual video outputs, gigabit Ethernet, and USB 3.0, capable of running full Linux distributions in addition to lightweight embedded workloads.', 'A Broadcom system-on-chip integrates the ARM Cortex-A72 CPU cores, GPU, and peripheral controllers on one die; the board boots a full operating system from an SD card, after which software running on Linux (rather than bare-metal firmware) controls the 40-pin GPIO header for hardware interfacing.', 'Home automation and media center hubs, computer vision and machine learning edge projects, retro gaming emulation, full Linux-based robotics controllers.', 'Full general-purpose computer capability including networking and video, huge software ecosystem via Linux, powerful multi-core CPU.', 'Requires a full boot process unlike instant-on microcontrollers, higher power consumption, GPIO is not truly real-time without extra care.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Raspberry Pi 4 Model B - Top.jpg', NULL, 'https://datasheets.raspberrypi.com/rpi4/raspberry-pi-4-datasheet.pdf', '{"CPU": "Quad-core Cortex-A72 @ 1.5GHz", "RAM": "2GB-8GB LPDDR4", "GPIO": "40-pin header", "Connectivity": "Gigabit Ethernet, Wi-Fi, Bluetooth 5.0"}'::jsonb, '{"development board","raspberry pi","single board computer","linux"}', 'intermediate')
