insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('raspberry-pi-pico', 'Raspberry Pi Pico', 'Development Boards', 'Raspberry Pi Foundation', 'Low-cost microcontroller board built around the Raspberry Pi Foundation''s own RP2040 chip.', 'The Raspberry Pi Pico is a compact, breadboard-friendly microcontroller board using the in-house designed RP2040, notable for its dual-core Cortex-M0+ processor and unique Programmable I/O (PIO) blocks that can offload custom digital protocols from the main CPU.', 'Two Cortex-M0+ cores run user code while the RP2040''s PIO state machines execute tiny custom programs to generate or receive precisely timed digital signals independently of the CPU, letting the Pico bit-bang protocols like WS2812 timing or custom serial formats without consuming CPU cycles.', 'Low-cost embedded projects needing precise timing, USB-connected sensor and controller projects, educational microcontroller programming in MicroPython or C.', 'Very low cost, unique PIO peripheral for flexible custom I/O, dual-core processing, both C/C++ SDK and MicroPython supported.', 'No built-in wireless on the base Pico (Pico W adds it), fewer analog inputs than some competing boards.', NULL, NULL, 'https://datasheets.raspberrypi.com/pico/pico-datasheet.pdf', '{"Microcontroller": "RP2040 dual-core Cortex-M0+ @ 133MHz", "Flash": "2MB", "GPIO": "26 multi-function pins", "Analog Inputs": "3 (12-bit ADC)"}'::jsonb, '{"development board","raspberry pi pico","rp2040","microcontroller"}', 'intermediate')
