insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('esp32-devkitv1', 'ESP32 DevKit V1', 'Development Boards', 'Espressif', 'Breadboard-friendly development board exposing the ESP32-WROOM-32 module''s pins with onboard USB programming.', 'The ESP32 DevKit V1 wraps the ESP32-WROOM-32 module with a USB-to-serial chip, voltage regulator, and breadboard-compatible pin spacing, giving a ready-to-program Wi-Fi and Bluetooth board that plugs directly into a standard breadboard.', 'A CP2102 or CH340 USB-to-UART bridge converts USB serial data to the UART lines the ESP32 uses for flashing firmware and serial debugging, while an onboard AMS1117-3.3 regulator steps the USB 5V down to the 3.3V the ESP32 module requires.', 'Wi-Fi and Bluetooth IoT prototyping on a breadboard, home automation nodes, wireless sensor projects, MicroPython and Arduino-core development.', 'Plug-and-play USB programming without an external programmer, breadboard-friendly pin spacing, access to the ESP32''s full wireless capability.', 'Board width varies by manufacturer and can be too wide for a single breadboard channel, GPIO pin numbering can be confusing across variants.', NULL, NULL, NULL, '{"Module": "ESP32-WROOM-32", "USB Bridge": "CP2102 or CH340", "GPIO": "~25 usable pins broken out", "Operating Voltage": "3.3V logic, 5V USB input"}'::jsonb, '{"development board","esp32","wifi","bluetooth"}', 'intermediate')
