insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('nodemcu-esp8266', 'NodeMCU (ESP8266)', 'Development Boards', 'Espressif', 'Breadboard-friendly Wi-Fi development board built around the ESP-12E module and open-source firmware roots.', 'NodeMCU began as an open-source Lua firmware project for the ESP8266 and today the name commonly refers to the widely cloned development board that pairs an ESP-12E module with USB programming circuitry, giving an inexpensive way to add Wi-Fi to a project.', 'Like other ESP8266 boards, an onboard USB-to-serial chip handles firmware flashing, and once programmed the ESP8266 runs application code (in Arduino C++, Lua, or MicroPython) that manages GPIO and the Wi-Fi radio to join or host wireless networks.', 'Wi-Fi controlled home automation, simple web server and IoT dashboard projects, low-cost wireless sensor nodes.', 'Very low cost, large hobbyist community and documentation, straightforward USB programming workflow via the Arduino IDE.', 'Confusing GPIO-to-silkscreen pin numbering on many board revisions, only one analog input pin, less processing power than ESP32 boards.', NULL, NULL, NULL, '{"Module": "ESP-12E (ESP8266)", "USB Bridge": "CP2102 or CH340", "GPIO": "~11 usable pins", "Analog Input": "1 (0-3.3V via onboard divider)"}'::jsonb, '{"development board","nodemcu","esp8266","wifi"}', 'beginner')
