insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('dht22-sensor', 'DHT22 Temperature & Humidity Sensor', 'Sensors', 'Aosong', 'Digital sensor module that reports both temperature and relative humidity over a single data wire.', 'The DHT22 (also sold as AM2302) combines a capacitive humidity sensing element and a thermistor with a small onboard controller that digitizes and transmits both readings over a single-wire digital protocol, avoiding the need for analog signal conditioning.', 'A capacitive humidity element changes capacitance as it absorbs or releases moisture from the air, and a thermistor changes resistance with temperature; an internal microcontroller samples both, converts them to calibrated digital values, and transmits them as a timed pulse-width digital signal on request.', 'Weather stations, greenhouse and terrarium climate monitoring, HVAC data logging, general environmental sensing projects.', 'Single digital pin interface simplifies wiring, factory-calibrated output avoids manual calibration, reasonably accurate for hobbyist use.', 'Slow sample rate of about once every two seconds, timing-sensitive protocol can be finicky with long wires, moderate accuracy compared to industrial sensors.', NULL, NULL, 'https://www.sparkfun.com/datasheets/Sensors/Temperature/DHT22.pdf', '{"Humidity Range": "0-100% RH, +/-2% accuracy", "Temperature Range": "-40C to 80C, +/-0.5C accuracy", "Interface": "Single-wire digital", "Supply Voltage": "3.3V-6V"}'::jsonb, '{"sensor","temperature","humidity","dht22"}', 'beginner')
