insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('hc-sr04-sensor', 'HC-SR04 Ultrasonic Distance Sensor', 'Sensors', 'Generic/ITead', 'Ultrasonic ranging module that measures distance by timing an echoed sound pulse, a hobbyist classic.', 'The HC-SR04 emits a burst of 40kHz ultrasonic sound and measures the time it takes for the echo to return, converting that time-of-flight into a distance reading with a simple two-pin trigger and echo interface.', 'Triggering a short pulse causes the transmitter transducer to emit eight cycles of 40kHz ultrasound; the receiver transducer detects the reflected echo and the module outputs a pulse whose duration is proportional to the round-trip travel time, which combined with the speed of sound gives the distance to the nearest reflective object.', 'Obstacle avoidance in robots, parking sensor projects, liquid level measurement, simple gesture or presence detection.', 'Simple two-pin digital interface, inexpensive and widely available, reasonably accurate over its rated range.', 'Struggles with soft or angled surfaces that scatter sound, minimum range limitation, timing must be read precisely by the microcontroller.', NULL, NULL, 'https://cdn.sparkfun.com/datasheets/Sensors/Proximity/HCSR04.pdf', '{"Range": "2cm-400cm", "Accuracy": "~3mm", "Measuring Angle": "15 deg", "Supply Voltage": "5V"}'::jsonb, '{"sensor","ultrasonic","distance","hc-sr04"}', 'beginner')
