insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('pir-hcsr501-sensor', 'PIR Motion Sensor (HC-SR501)', 'Sensors', 'Generic', 'Passive infrared sensor module that detects movement of warm bodies such as people or animals.', 'The HC-SR501 module houses a pyroelectric sensor behind a Fresnel lens that detects changes in infrared radiation across its field of view, triggering a digital output high whenever motion is sensed, with adjustable sensitivity and hold-time potentiometers.', 'The pyroelectric element generates a small voltage change when the infrared radiation falling on it changes, which happens as a warm object like a person moves across the segmented field of view created by the Fresnel lens; onboard circuitry amplifies and debounces this signal into a clean digital output pulse.', 'Motion-activated lighting, security and intrusion alarm systems, automatic hand dryers and faucets, energy-saving occupancy sensing.', 'Passive detection requires no emitted signal so it draws very little power, simple digital output, adjustable sensitivity and delay.', 'Can false-trigger on sudden temperature changes or direct sunlight, needs a warm-up period after power-on, cannot detect stationary occupants.', NULL, NULL, NULL, '{"Detection Range": "up to 7m", "Detection Angle": "~120 deg", "Supply Voltage": "4.5V-20V", "Output": "Digital high/low"}'::jsonb, '{"sensor","pir","motion","security"}', 'beginner')
