insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('mpu6050-sensor', 'MPU6050 6-Axis IMU', 'Sensors', 'TDK InvenSense', 'Combined 3-axis accelerometer and 3-axis gyroscope on one chip, communicating over I2C.', 'The MPU6050 integrates a MEMS accelerometer and a MEMS gyroscope along with a digital motion processor on a single die, giving six degrees of motion sensing (acceleration and rotation on all three axes) accessible over a simple I2C bus.', 'Microelectromechanical (MEMS) proof masses shift under acceleration or Coriolis forces from rotation, and that tiny physical displacement is converted into a proportional electrical signal by onboard capacitive sensing circuitry, which is then digitized and made available through I2C registers.', 'Drone and robot orientation stabilization, gesture recognition, step counting and activity tracking, camera gimbal stabilization.', 'Combines accelerometer and gyroscope in one small package, simple I2C interface, includes an onboard digital motion processor for sensor fusion.', 'Gyroscope readings drift over time and need periodic correction, sensitive to vibration noise without filtering.', NULL, NULL, 'https://invensense.tdk.com/wp-content/uploads/2015/02/MPU-6000-Datasheet1.pdf', '{"Axes": "3-axis accel + 3-axis gyro", "Interface": "I2C (up to 400kHz)", "Accel Range": "+/-2g to +/-16g", "Gyro Range": "+/-250 to +/-2000 deg/s"}'::jsonb, '{"sensor","imu","accelerometer","gyroscope","i2c"}', 'intermediate')
