insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ldr-photoresistor', 'LDR (Photoresistor)', 'Sensors', 'Generic', 'Light-dependent resistor whose resistance drops sharply as ambient light increases.', 'A light-dependent resistor, built from cadmium sulfide or similar photoconductive material, is one of the simplest possible light sensors: no power supply is needed on the sensing element itself, and its resistance simply changes with incident light intensity.', 'Photons striking the semiconductor material excite electrons into the conduction band, increasing the number of free charge carriers and therefore lowering the material''s electrical resistance; more incident light means more excited carriers and lower resistance, while darkness leaves resistance high.', 'Automatic streetlight and nightlight circuits, simple light-triggered alarms, ambient light measurement in photography meters, dark-detecting robots.', 'Extremely simple and cheap, no active circuitry required on the sensing element, wide dynamic resistance range between light and dark.', 'Slow response time compared to photodiodes, imprecise and nonlinear response, sensitivity varies noticeably between individual units.', NULL, NULL, NULL, '{"Dark Resistance": "~1Mohm", "Light Resistance (10 lux)": "~10-20kohm", "Response Time": "20-30ms", "Package": "THT 5mm disc"}'::jsonb, '{"sensor","ldr","photoresistor","light"}', 'beginner')
