insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('bmp280-sensor', 'BMP280 Barometric Pressure Sensor', 'Sensors', 'Bosch Sensortec', 'High-precision digital sensor measuring barometric pressure and temperature over I2C or SPI.', 'The BMP280 is a compact MEMS pressure sensor commonly used to estimate altitude, since atmospheric pressure decreases predictably with height, and it also reports temperature so that pressure readings can be temperature-compensated.', 'A MEMS piezoresistive membrane flexes slightly as ambient pressure changes, altering its electrical resistance in a way the onboard ADC and signal-conditioning circuitry converts into a calibrated digital pressure reading, using factory-stored calibration coefficients to correct for temperature and manufacturing variation.', 'Altitude estimation for drones and weather balloons, weather station barometric logging, indoor/outdoor altitude change detection.', 'High resolution pressure measurement, small footprint, supports both I2C and SPI for flexible wiring.', 'Altitude derived from pressure drifts with changing weather systems, needs a local sea-level reference for accurate absolute altitude.', NULL, NULL, 'https://www.bosch-sensortec.com/media/boschsensortec/downloads/datasheets/bst-bmp280-ds001.pdf', '{"Pressure Range": "300-1100 hPa", "Interface": "I2C / SPI", "Resolution": "~0.16m altitude equivalent", "Supply Voltage": "1.71V-3.6V"}'::jsonb, '{"sensor","pressure","altitude","bmp280"}', 'intermediate')
