insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('soil-moisture-sensor', 'Soil Moisture Sensor', 'Sensors', 'Generic', 'Two-probe sensor that estimates soil moisture by measuring the electrical conductivity between its prongs.', 'A capacitive or resistive soil moisture sensor is inserted into potting soil, with a comparator board providing both an analog output proportional to moisture level and a simple digital threshold output for basic wet/dry detection.', 'Resistive versions measure the conductivity between two exposed probes, which increases as water content (and dissolved minerals) in the soil rises; capacitive versions instead measure the change in capacitance of the soil dielectric, avoiding the probe corrosion that plagues resistive designs.', 'Automated plant watering systems, garden and greenhouse irrigation control, agricultural soil monitoring projects.', 'Simple analog interface easy to read with any microcontroller ADC, inexpensive, immediate readings.', 'Resistive versions corrode over time from constant electrolysis in wet soil, readings vary with soil type and require per-setup calibration.', NULL, NULL, NULL, '{"Output": "Analog voltage + digital threshold", "Supply Voltage": "3.3V-5V", "Interface": "Analog + comparator digital"}'::jsonb, '{"sensor","soil moisture","agriculture","analog"}', 'beginner')
