insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('mq2-gas-sensor', 'MQ-2 Gas Sensor', 'Sensors', 'Winsen', 'Semiconductor gas sensor module sensitive to smoke and combustible gases such as LPG, propane, and methane.', 'The MQ-2 uses a tin dioxide sensing element heated by an internal coil; the element''s conductivity changes in the presence of combustible gases and smoke particles, giving a low-cost way to build gas leak and smoke detection circuits.', 'At its operating temperature, maintained by an internal heater, the tin dioxide sensing layer''s electrical conductivity increases in proportion to the concentration of reducing gases (such as LPG, methane, or smoke particulates) adsorbed onto its surface, which the onboard circuit converts into an analog voltage.', 'Gas leak detection and alarm circuits, smoke detection projects, air quality monitoring for combustible gases, kitchen safety devices.', 'Sensitive to a broad range of combustible gases and smoke, low cost, simple analog output.', 'Requires several minutes of warm-up and burn-in for stable readings, not gas-specific so cannot distinguish which gas is present, sensitivity drifts over the sensor''s lifetime.', NULL, NULL, NULL, '{"Detects": "LPG, propane, methane, smoke", "Output": "Analog voltage + digital threshold", "Supply Voltage": "5V", "Preheat Time": "~20s minimum, 24-48h for stable calibration"}'::jsonb, '{"sensor","gas","smoke","mq2","safety"}', 'intermediate')
