insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('hc-05-bluetooth', 'HC-05 Bluetooth Module', 'Communication Modules', 'Generic/ITead', 'Classic Bluetooth serial module that transparently bridges UART data over a Bluetooth SPP link.', 'The HC-05 pairs a Bluetooth radio with an onboard controller running the Serial Port Profile (SPP), so any microcontroller with a UART can send and receive data wirelessly to a phone or PC exactly as if it were a wired serial connection.', 'The module handles the entire Bluetooth pairing, connection, and Serial Port Profile stack internally; bytes written to its UART RX pin are transmitted over the Bluetooth link and appear at the receiving device''s virtual serial port, and vice versa, making the wireless link invisible to the application code.', 'Wireless serial control from a smartphone app, Bluetooth-controlled robots and RC vehicles, wireless data logging to a PC.', 'Extremely simple UART pass-through interface, works with countless existing serial terminal apps, both master and slave mode support.', 'Classic Bluetooth has shorter range and higher power draw than BLE, pairing process can be finicky, being superseded by BLE modules in new designs.', NULL, NULL, NULL, '{"Bluetooth Version": "2.0 + EDR", "Range": "~10m", "Interface": "UART (TTL, 3.3V logic)", "Supply Voltage": "3.3V-6V"}'::jsonb, '{"communication","bluetooth","wireless","serial"}', 'beginner')
