insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('nrf24l01-module', 'nRF24L01 2.4GHz Transceiver', 'Communication Modules', 'Nordic Semiconductor', 'Low-power 2.4GHz radio module used to build simple point-to-point or small mesh wireless links between microcontrollers.', 'The nRF24L01 is a self-contained 2.4GHz transceiver with an SPI interface, popular for building custom short-range wireless links between two or more microcontrollers without relying on Wi-Fi or Bluetooth infrastructure.', 'An onboard RF synthesizer generates a 2.4GHz carrier that is digitally modulated with data from the SPI interface; a built-in packet engine handles addressing, automatic acknowledgment, and retransmission, so the connected microcontroller only needs to push and pull data bytes over SPI rather than managing raw radio timing.', 'Wireless RC transmitter and receiver links, multi-node sensor networks, simple wireless game controllers, wireless keyboard and mouse projects.', 'Very low cost and low power consumption, configurable data rate and channel, built-in auto-acknowledge and retry reduces packet loss handling.', 'Requires careful SPI wiring and a stable 3.3V supply with good decoupling, shorter effective range than Wi-Fi or LoRa modules.', NULL, NULL, 'https://www.sparkfun.com/datasheets/Wireless/Nordic/nRF24L01_prelim_prod_spec_1_2.pdf', '{"Frequency": "2.4-2.525GHz ISM band", "Interface": "SPI", "Data Rate": "250kbps-2Mbps", "Supply Voltage": "1.9V-3.6V (3.3V typical)"}'::jsonb, '{"communication","rf","wireless","spi","nrf24l01"}', 'intermediate')
