insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('sim800l-module', 'SIM800L GSM/GPRS Module', 'Communication Modules', 'SIMCom', 'Compact quad-band GSM/GPRS module that lets a microcontroller send SMS, make calls, and access mobile data.', 'The SIM800L brings cellular connectivity to embedded projects, letting a microcontroller send SMS text messages, place voice calls, or exchange data over GPRS by issuing simple AT commands over a UART connection to a SIM card equipped module.', 'The onboard baseband processor handles the full GSM protocol stack; the connected microcontroller communicates over UART using standardized AT commands to request actions like sending an SMS or opening a data connection, and the module manages all cellular network registration and signaling internally.', 'Remote SMS alert systems, GPS tracker data uplink, IoT devices in areas without Wi-Fi coverage, remote-controlled devices via SMS command.', 'Provides cellular connectivity without Wi-Fi infrastructure, simple AT command interface, supports SMS, voice, and GPRS data.', 'Needs a robust power supply able to handle 2A current spikes during transmission bursts, requires an active SIM card and antenna for reliable operation.', NULL, NULL, NULL, '{"Bands": "Quad-band 850/900/1800/1900MHz", "Interface": "UART (AT commands)", "Peak Current": "up to 2A during transmit", "Supply Voltage": "3.4V-4.4V"}'::jsonb, '{"communication","gsm","gprs","cellular","sim800l"}', 'advanced')
