insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('rc522-rfid-module', 'RC522 RFID Reader Module', 'Communication Modules', 'NXP (MFRC522)', '13.56MHz RFID/NFC reader-writer module used to read tags and cards over short range via SPI.', 'Built around the NXP MFRC522 chip, this module reads and writes 13.56MHz RFID tags and cards, commonly used with the credit-card-sized MIFARE tags included in most starter kits, communicating with a host microcontroller over SPI.', 'The reader generates a 13.56MHz electromagnetic field through its antenna coil; a nearby passive RFID tag draws power from that field to run its own tiny chip and modulates the field to transmit its stored ID or data back, which the MFRC522 demodulates and passes to the host over SPI.', 'Access control and door lock systems, attendance and time-tracking systems, inventory and asset tagging, hobbyist NFC experiments.', 'Simple SPI interface with mature libraries, works with widely available inexpensive MIFARE tags and cards, both read and write capable.', 'Short read range of only a few centimeters, susceptible to interference from metal near the antenna, not encrypted by default on basic tags.', NULL, NULL, NULL, '{"Frequency": "13.56MHz", "Interface": "SPI", "Read Range": "~3cm typical", "Supply Voltage": "3.3V"}'::jsonb, '{"communication","rfid","nfc","spi","access control"}', 'intermediate')
