insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('sx1278-lora-module', 'SX1278 LoRa Module', 'Communication Modules', 'Semtech', 'Long-range, low-power radio module using LoRa spread-spectrum modulation for kilometer-scale wireless links.', 'The SX1278 implements Semtech''s LoRa modulation, a chirp spread-spectrum technique that trades data rate for dramatically extended range and receiver sensitivity, letting simple modules communicate several kilometers apart on unlicensed sub-GHz bands.', 'LoRa encodes data as chirps that sweep across a wide bandwidth, spreading the signal''s energy so it can be recovered even far below the noise floor using correlation techniques in the receiver; this spread-spectrum approach is what lets LoRa achieve much longer range than conventional narrowband radios at similar power levels.', 'Long-range IoT sensor networks, LoRaWAN gateway nodes, remote environmental monitoring, agricultural and infrastructure telemetry over kilometers.', 'Exceptional range compared to Wi-Fi or Bluetooth for the same transmit power, low power consumption suited to battery operation, operates on license-free sub-GHz bands.', 'Low data rate unsuitable for anything beyond small telemetry packets, regional frequency band regulations must be respected, more complex to configure than simpler radio modules.', NULL, NULL, NULL, '{"Frequency": "433/868/915MHz variants", "Interface": "SPI", "Range": "up to several km line-of-sight", "Supply Voltage": "3.3V"}'::jsonb, '{"communication","lora","long range","iot","spi"}', 'advanced')
