insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lcd-16x2-hd44780', '16x2 LCD Display (HD44780)', 'Displays', 'Generic (HD44780 controller)', 'Classic alphanumeric character LCD displaying 16 columns by 2 rows of text, driven by the ubiquitous HD44780 controller.', 'The 16x2 character LCD has been the default text display for hobby electronics for decades, using the HD44780 (or a compatible) controller chip to manage character generation, cursor position, and the parallel or I2C-backpack interface.', 'The HD44780 controller stores a character generator ROM mapping byte codes to dot-matrix pixel patterns; the host microcontroller sends command and data bytes over a 4-bit or 8-bit parallel bus (or through an I2C backpack that serializes the same commands) to select cursor position and write characters, which the controller then renders onto the liquid crystal matrix.', 'Menu and status displays for embedded projects, simple sensor readouts, calculator and clock projects, 3D printer control panels.', 'Extremely well documented with mature libraries, readable in direct sunlight unlike many OLEDs, cheap and widely available.', 'Text-only display with no graphics capability, requires many GPIO pins unless using an I2C backpack, limited viewing angle on cheaper panels.', NULL, NULL, NULL, '{"Resolution": "16 columns x 2 rows characters", "Controller": "HD44780 compatible", "Interface": "4/8-bit parallel or I2C (with backpack)", "Supply Voltage": "5V"}'::jsonb, '{"display","lcd","hd44780","character display"}', 'beginner')
