insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ssd1306-oled', 'SSD1306 OLED Display', 'Displays', 'Solomon Systech', 'Small monochrome OLED display module, commonly 128x64 pixels, driven over I2C or SPI.', 'The SSD1306 is a display driver IC bonded to a tiny OLED panel, typically 0.96 inches diagonal at 128x64 pixel resolution, offering crisp, high-contrast graphics with no backlight required since each pixel emits its own light.', 'Each pixel is an individually addressable organic LED that emits light directly when current flows through it, eliminating the need for a backlight; the SSD1306 controller holds a full frame buffer in its internal GRAM and refreshes the panel autonomously once the host writes pixel data over I2C or SPI.', 'Compact status and sensor readout displays, wearable device screens, simple graphical menus and icons, battery-powered project displays.', 'Very high contrast with true blacks since unlit pixels emit no light, low power for mostly-dark content, simple I2C wiring with just two data lines.', 'Susceptible to burn-in with static images over long periods, monochrome only, smaller viewing area than LCD panels of similar cost.', NULL, NULL, 'https://cdn-shop.adafruit.com/datasheets/SSD1306.pdf', '{"Resolution": "128x64 pixels typical", "Interface": "I2C or SPI", "Supply Voltage": "3.3V-5V", "Display Type": "Monochrome OLED"}'::jsonb, '{"display","oled","ssd1306","i2c","graphics"}', 'intermediate')
