insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('7-segment-display', '7-Segment Display', 'Displays', 'Kingbright', 'Numeric display made of seven LED segments arranged to form digits 0-9 and some letters.', 'A 7-segment display packages seven individually addressable LED bars (plus often a decimal point) behind a diffused lens, and lighting the right combination of segments forms any digit from 0 to 9 or a handful of letters.', 'Each of the seven segments is an independent LED sharing a common anode or common cathode connection; driving the correct subset of segment pins high (or low, depending on common type) illuminates exactly the segments needed to visually form the desired digit.', 'Digital clocks and counters, simple numeric readouts on meters, scoreboard and timer projects, calculator-style displays.', 'Extremely legible numeric display, simple direct-drive wiring for a single digit, no display controller chip required for small counts.', 'Requires a current-limiting resistor per segment, driving multiple digits needs multiplexing or a driver IC, cannot display arbitrary graphics.', NULL, NULL, NULL, '{"Segments": "7 + decimal point", "Type": "Common anode or common cathode", "Forward Voltage": "~2V per segment", "Package": "THT 0.56in-0.8in digit"}'::jsonb, '{"display","7-segment","led","numeric"}', 'beginner')
