insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ili9341-tft', 'ILI9341 TFT LCD Display', 'Displays', 'Ilitek', 'Full-color 2.4-2.8 inch TFT LCD module, commonly 240x320 pixels, driven over SPI.', 'The ILI9341 driver IC controls a full-color thin-film-transistor LCD panel, giving embedded projects a bright, colorful graphical display capable of showing images, fonts, and simple UIs at a resolution far beyond a character LCD.', 'Each pixel contains red, green, and blue sub-pixel filters backed by a thin-film transistor that controls the liquid crystal''s twist and therefore how much backlight passes through; the ILI9341 controller holds pixel data in its internal GRAM and streams it to the panel''s row and column drivers to continuously refresh the image.', 'Graphical user interfaces for embedded devices, handheld game and instrument displays, camera and sensor visualization, touchscreen projects when paired with a resistive or capacitive overlay.', 'Full color graphics far beyond character displays, fast SPI-based updates suitable for simple animation, widely supported by graphics libraries.', 'Requires more GPIO pins and faster SPI clock than simpler displays, higher power draw due to backlight, needs a graphics library and more RAM/flash on the host.', NULL, NULL, 'https://cdn-shop.adafruit.com/datasheets/ILI9341.pdf', '{"Resolution": "240x320 pixels", "Interface": "SPI (or parallel)", "Colors": "18-bit (262K colors)", "Supply Voltage": "3.3V"}'::jsonb, '{"display","tft","ili9341","spi","graphics"}', 'advanced')
