insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('nokia5110-lcd', 'Nokia 5110 LCD Display', 'Displays', 'Philips (PCD8544 controller)', 'Small monochrome graphic LCD salvaged in concept from the classic Nokia 5110 phone, popular for low-power projects.', 'Based on the PCD8544 controller originally used in the Nokia 5110 mobile phone, this 84x48 pixel monochrome LCD module offers basic graphics capability at extremely low power draw and low cost, making it a favorite for battery-powered instrument displays.', 'The PCD8544 controller maintains an internal display RAM mapped to the 84x48 pixel grid; the host writes commands and pixel data over a simple SPI-like serial interface, and the controller drives the LCD''s row and column electrodes to twist the liquid crystal at each addressed pixel, blocking or passing light from a small backlight.', 'Battery-powered instrument and meter displays, simple graphical status screens, retro-styled project displays, low-power wearable prototypes.', 'Very low power consumption, small SPI pin count, decent contrast without backlight for readability in bright conditions.', 'Small screen area and low resolution limit content, monochrome only, contrast can be sensitive to supply voltage and temperature.', NULL, NULL, NULL, '{"Resolution": "84x48 pixels", "Controller": "PCD8544", "Interface": "SPI (serial)", "Supply Voltage": "3.3V"}'::jsonb, '{"display","lcd","nokia5110","pcd8544","spi"}', 'intermediate')
