insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('5v-relay-module', '5V SPDT Relay Module', 'Relays', 'Songle', 'Single-channel relay breakout board that lets a microcontroller switch mains-voltage or high-current loads safely.', 'This breakout board pairs an electromechanical relay with a driver transistor, flyback diode, and opto-isolation on many versions, letting a 5V logic signal from a microcontroller safely switch a completely separate high-voltage or high-current circuit.', 'A small coil current from the driver transistor creates a magnetic field that pulls an internal armature, mechanically closing (or opening) a set of physically separate contacts; because the control coil and the switched contacts are electrically isolated, a low-voltage logic signal can control a circuit at a totally different voltage and current level.', 'Switching mains-voltage lamps and appliances from an Arduino, controlling solenoid valves and larger motors, home automation relay banks.', 'True electrical isolation between control and load circuits, can switch both AC and DC loads, simple digital control interface.', 'Mechanical contacts wear out over repeated switching cycles, audible click and slower switching speed than solid-state alternatives, coil can generate voltage spikes without a flyback diode.', NULL, NULL, NULL, '{"Coil Voltage": "5V", "Contact Rating": "10A @ 250VAC / 10A @ 30VDC", "Type": "SPDT", "Isolation": "Opto-isolated trigger on most modules"}'::jsonb, '{"relay","switching","isolation","electromechanical"}', 'intermediate')
