insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('solid-state-relay', 'Solid State Relay (SSR)', 'Relays', 'Fotek', 'Relay with no moving parts, using a TRIAC or MOSFET output stage switched on via an internal optocoupler.', 'A solid state relay achieves the same isolated switching function as an electromechanical relay but uses a light-triggered semiconductor output stage instead of a mechanical armature, giving silent, faster, and far longer-lived switching for many applications.', 'An LED inside the SSR''s input stage optically couples the control signal to a phototriac or photodiode-driven output stage, which then triggers a TRIAC or set of MOSFETs to switch the load; because the coupling is purely optical, the control and load circuits remain fully electrically isolated with no mechanical contacts to wear out.', 'High-cycle-count industrial switching, heater and motor control where silent operation matters, dusty or vibration-prone environments unsuitable for mechanical relays.', 'No mechanical wear so far higher switching cycle life, silent operation, much faster switching speed than electromechanical relays.', 'Generates more heat in the on-state and often needs a heatsink, more expensive than an equivalent electromechanical relay, can fail short-circuit rather than open.', NULL, NULL, NULL, '{"Control Voltage": "3-32VDC input typical", "Load Rating": "e.g. 25A-40A @ 240VAC", "Isolation": "Optical, ~4000V typical", "Package": "Panel-mount module"}'::jsonb, '{"relay","solid state","ssr","switching"}', 'advanced')
