insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('dc-motor', 'Brushed DC Motor', 'Motors', 'Generic', 'Simple two-terminal motor that spins continuously in one direction when a DC voltage is applied.', 'A brushed DC motor is the simplest and most common electric motor for hobby projects, converting DC electrical energy into continuous rotary motion through the interaction of a permanent magnet stator and a spinning wound rotor fed current via mechanical brushes.', 'Current flowing through the rotor''s coil windings, sitting inside the field of stationary permanent magnets, creates a force on the coil according to the motor effect (Lorentz force); mechanical brushes and a commutator switch which coil is energized as the rotor spins, keeping the torque acting in a consistent rotational direction.', 'Simple robotics wheels and propulsion, cooling fans, toy and hobby mechanisms, pump and actuator drives.', 'Very simple to drive, needing only a voltage and current source (often through an H-bridge for direction control), cheap and available in countless sizes.', 'Brushes wear out over time and create electrical noise, less efficient and precise than brushless or stepper alternatives, speed varies with load without feedback control.', NULL, NULL, NULL, '{"Voltage": "1.5V-24V common hobby range", "No-load Speed": "varies widely, e.g. 3000-12000 RPM", "Interface": "Two-wire DC, direction via polarity", "Package": "Cylindrical can motor"}'::jsonb, '{"motor","dc motor","actuator","brushed"}', 'beginner')
