insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('28byj48-stepper', 'Stepper Motor (28BYJ-48)', 'Motors', 'Generic', 'Small geared stepper motor that rotates in precise fixed-angle steps, popular in beginner robotics kits.', 'The 28BYJ-48 is an inexpensive 5V unipolar stepper motor with an internal gear reduction, commonly bundled with a ULN2003 driver board, that moves in small precise steps rather than spinning continuously, making it easy to control exact rotation angles.', 'Four electromagnetic coil phases inside the motor are energized in a specific sequence, each pulling the rotor''s teeth to align with the next energized coil pole; stepping through the sequence in order rotates the shaft by one small fixed angle per step, and the internal gearbox further divides each step into a much finer output rotation.', 'Camera pan-tilt mechanisms, small CNC and 3D printer axes, precise valve or dial positioning, educational robotics kits.', 'Precise open-loop position control without needing an encoder, holds position with power applied, simple sequencing logic.', 'Low speed and torque compared to its size, can lose steps (position) if overloaded, driver board and 4-wire control add complexity versus a simple DC motor.', NULL, NULL, NULL, '{"Step Angle": "5.625/64 deg per step (with gearbox)", "Gear Ratio": "~1:64", "Supply Voltage": "5V", "Driver": "ULN2003 (commonly bundled)"}'::jsonb, '{"motor","stepper","28byj-48","precision"}', 'intermediate')
