insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('sg90-servo', 'Servo Motor (SG90)', 'Motors', 'TowerPro', 'Small PWM-controlled motor with precise angular positioning, a fixture of beginner robotics kits.', 'The SG90 micro servo packages a small DC motor, gear reduction, and a position feedback potentiometer inside one case with built-in control electronics, so it holds a commanded angle in response to a simple PWM signal rather than spinning freely.', 'The internal control circuit compares the pulse width of the incoming PWM signal, typically 1-2ms every 20ms, against the shaft position reported by an internal potentiometer, then drives the motor in the direction needed to reduce the error until the shaft angle matches the commanded position.', 'Robot arm joints and grippers, RC vehicle steering, pan-tilt camera mounts, automated door latches and small mechanisms.', 'Simple single-wire PWM control for precise angle positioning, self-contained closed-loop control needs no external feedback wiring, cheap and widely available.', 'Limited to roughly 180 degrees of rotation on standard versions, gears can strip under excessive load, positional accuracy limited by the internal potentiometer''s resolution.', NULL, NULL, NULL, '{"Voltage": "4.8V-6V", "Torque": "1.8kg-cm", "Rotation": "0-180 deg", "Control": "PWM, 50Hz, 1-2ms pulse width"}'::jsonb, '{"servo","motor","actuator","pwm"}', 'beginner')
