insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('bldc-motor', 'Brushless DC (BLDC) Motor', 'Motors', 'Generic', 'Electronically commutated motor offering higher efficiency and lifespan than brushed designs, common in drones.', 'A brushless DC motor replaces the mechanical brushes and commutator of a traditional DC motor with electronic commutation, using an external controller to energize stator windings in the correct sequence based on rotor position, giving higher efficiency, longer life, and higher achievable speeds.', 'An electronic speed controller switches current through multiple stator coil phases in a precise sequence, timed either from Hall-effect sensors or by sensing the back-EMF of unpowered phases, so the resulting rotating magnetic field continuously pulls the permanent-magnet rotor around without any physical brush contact.', 'Multirotor drone propulsion, RC car and aircraft motors, cooling fans in demanding applications, electric skateboard and e-bike drives.', 'No brush wear so much longer service life, higher efficiency and power density than brushed motors, capable of very high RPM.', 'Requires a dedicated electronic speed controller to commutate the phases, more complex and expensive than a simple brushed DC motor.', NULL, NULL, NULL, '{"Phases": "3-phase typical", "KV Rating": "varies, e.g. 1000-2300 KV for drone motors", "Control": "Requires ESC (electronic speed controller)", "Package": "Outrunner or inrunner can"}'::jsonb, '{"motor","brushless","bldc","drone"}', 'advanced')
