insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('l298n-driver', 'L298N Dual H-Bridge Motor Driver', 'Motor Drivers', 'STMicroelectronics', 'Classic dual H-bridge driver module used to control the speed and direction of two DC motors or one stepper.', 'The L298N breakout board wraps ST''s L298 dual full-bridge driver IC with terminal blocks, protection diodes, and an onboard 5V regulator, giving beginners a rugged, easy-to-wire way to drive two DC motors or one bipolar stepper motor from microcontroller logic signals.', 'Each H-bridge uses four switching elements arranged so that reversing which diagonal pair conducts reverses the current direction through the motor, allowing forward, reverse, and brake states; a PWM signal on the enable pin controls the average voltage delivered to the motor and therefore its speed.', 'Robot chassis wheel motor control, small CNC or 3D printer stepper driving, general bidirectional DC motor control from a microcontroller.', 'Can drive two motors independently, rugged and tolerant of wiring mistakes, simple direction and PWM speed control logic.', 'Significant voltage drop across the internal transistors wastes power as heat compared to MOSFET-based drivers, bulky compared to modern integrated driver ICs.', NULL, NULL, 'https://www.st.com/resource/en/datasheet/l298.pdf', '{"Channels": "2 (dual H-bridge)", "Motor Supply Voltage": "5V-35V", "Peak Current": "2A per channel", "Logic Voltage": "5V"}'::jsonb, '{"motor driver","h-bridge","l298n","dc motor"}', 'intermediate')
