insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('a4988-stepper-driver', 'A4988 Stepper Motor Driver', 'Motor Drivers', 'Allegro MicroSystems', 'Compact bipolar stepper driver module offering microstepping, widely used on 3D printers and CNC machines.', 'The A4988 is a small breakout module built around Allegro''s chip of the same name, translating a simple step-and-direction signal from a microcontroller into the precise current-controlled coil switching a bipolar stepper motor needs, with adjustable microstepping for smoother motion.', 'Each pulse on the STEP pin advances the motor by one (micro)step according to internal translator logic, which energizes the two motor coil phases in the correct sequence and current level; onboard current sensing and a chopper drive circuit regulate coil current independent of supply voltage, protecting the motor windings from excess current.', '3D printer axis and extruder stepper control, CNC router and laser cutter motion control, precision positioning stages.', 'Simple step/direction digital interface abstracts away complex coil switching, adjustable microstepping for smoother, quieter motion, adjustable current limit protects the motor.', 'Needs a heatsink for sustained higher current operation, current limit must be manually tuned via a small trimmer potentiometer, can be damaged by hot-plugging the motor connector.', NULL, NULL, 'https://www.allegromicro.com/-/media/files/datasheets/a4988-datasheet.pdf', '{"Motor Type": "Bipolar stepper", "Max Current": "2A per coil (with cooling)", "Microstepping": "Full to 1/16 step", "Logic Voltage": "3-5.5V"}'::jsonb, '{"motor driver","stepper","a4988","3d printer"}', 'advanced')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
