insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('drv8825-stepper-driver', 'DRV8825 Stepper Motor Driver', 'Motor Drivers', 'Texas Instruments', 'Higher-current, finer-microstepping successor to the A4988, popular for driving larger stepper motors.', 'The DRV8825 module offers the same simple step/direction interface as the A4988 but supports higher coil current and finer 1/32 microstepping, making it a common upgrade choice for 3D printers and CNC machines needing smoother or more powerful stepper motion.', 'Like the A4988, internal translator logic converts each STEP pulse into the correctly sequenced and current-regulated coil energization pattern for a bipolar stepper motor, using current chopping to hold coil current at the level set by the onboard trimmer regardless of supply voltage fluctuations.', 'Higher-torque 3D printer axes, CNC machine stepper motion, robotics requiring smoother finely-stepped motion than the A4988 provides.', 'Higher current handling than the A4988, finer 1/32 microstepping for smoother motion, pin-compatible with A4988 for easy upgrades.', 'Runs hotter at high current and needs a heatsink, current limit trimming still required and easy to set incorrectly, still susceptible to damage from hot-plugging.', NULL, NULL, 'https://www.ti.com/lit/ds/symlink/drv8825.pdf', '{"Motor Type": "Bipolar stepper", "Max Current": "2.2A per coil (with cooling)", "Microstepping": "Full to 1/32 step", "Logic Voltage": "3.3-5.25V"}'::jsonb, '{"motor driver","stepper","drv8825","3d printer"}', 'advanced')
