insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('bridge-rectifier', 'Bridge Rectifier', 'Power Electronics', 'Vishay', 'Four-diode module that converts full-wave AC input into pulsating DC output in a single compact package.', 'A bridge rectifier packages four diodes arranged in a diamond configuration into one component, so an AC source can be converted directly to full-wave rectified DC without needing a center-tapped transformer, simplifying countless power supply designs.', 'On each half-cycle of the AC input, a different diagonal pair of the four diodes conducts, always steering current through the load in the same direction regardless of which way the AC input is currently swinging, producing a pulsating but never-reversing output voltage across the load.', 'AC-to-DC conversion in linear and switching power supplies, motor drive input rectification, battery charger front ends.', 'Compact single-package solution replacing four discrete diodes, works without a center-tapped transformer, simple two-in-two-out wiring.', 'Two diode voltage drops in series reduce efficiency versus a center-tap design, generates heat proportional to load current that may need a heatsink at higher currents.', NULL, NULL, NULL, '{"Forward Current": "1A-35A depending on part", "Reverse Voltage": "50V-1000V depending on part", "Package": "THT bridge (round or square) or SMD"}'::jsonb, '{"power electronics","rectifier","bridge","ac-dc"}', 'intermediate')
