insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('bt136-triac', 'TRIAC (BT136)', 'Power Electronics', 'STMicroelectronics', 'Bidirectional thyristor capable of switching AC power in both current directions, common in dimmer circuits.', 'A TRIAC (triode for alternating current) can conduct current in either direction once triggered by a gate pulse, making it the standard component behind AC light dimmers, motor speed controllers, and other phase-controlled AC switching circuits.', 'Once triggered by a gate current pulse, the TRIAC latches into full conduction for the remainder of that AC half-cycle, staying on until the current naturally crosses zero; by delaying the gate trigger pulse relative to the AC zero-crossing, the fraction of each cycle the load receives power can be smoothly varied, producing a dimming or speed-control effect.', 'Household lamp dimmer switches, universal motor speed controllers (power tools, fans), solid-state AC relays and light-duty AC switching.', 'Switches AC current in both directions with a single component, low gate trigger current needed, enables smooth phase-angle power control.', 'Generates electrical noise and requires snubber circuits for inductive loads, not designed for DC switching, mishandling AC mains wiring is dangerous without proper isolation.', NULL, NULL, 'https://www.st.com/resource/en/datasheet/bt136.pdf', '{"Type": "Bidirectional thyristor (TRIAC)", "On-state RMS Current": "4A", "Blocking Voltage": "600V", "Package": "TO-220"}'::jsonb, '{"power electronics","triac","ac switching","dimmer"}', 'advanced')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
