insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('thyristor-scr', 'Thyristor (SCR)', 'Power Electronics', 'STMicroelectronics', 'Silicon-controlled rectifier that latches into conduction when triggered, used for high-power switching and control.', 'A silicon-controlled rectifier (SCR) is a four-layer semiconductor device that stays off until a gate pulse triggers it into conduction in one direction, after which it continues conducting until current falls below a holding threshold, regardless of further gate signals.', 'A small gate current injects carriers that trigger a regenerative feedback process across the device''s PNPN layers, snapping the SCR from a blocking state into full forward conduction; once latched on, the device stays conductive purely from the main current path until that current drops below the holding current, at which point it turns off naturally.', 'High-power DC and rectified-AC switching, crowbar overvoltage protection circuits, phase-controlled motor speed control, welding equipment power control.', 'Can switch very high currents and voltages, latching behavior means the gate signal only needs to be a brief pulse, robust in industrial power applications.', 'Once triggered it cannot be turned off by the gate, only by removing or reversing the main current, unsuitable for DC circuits without extra commutation circuitry.', NULL, NULL, NULL, '{"Type": "Unidirectional thyristor (SCR)", "On-state Current": "varies, e.g. 8A-25A common parts", "Blocking Voltage": "200V-1000V", "Package": "TO-220 / TO-247"}'::jsonb, '{"power electronics","thyristor","scr","switching"}', 'advanced')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
  working_principle = excluded.working_principle, applications = excluded.applications,
  advantages = excluded.advantages, disadvantages = excluded.disadvantages,
