insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('igbt', 'IGBT (Insulated Gate Bipolar Transistor)', 'Power Electronics', 'Infineon', 'Power switching device combining a MOSFET''s easy voltage-controlled gate with a bipolar transistor''s high current handling.', 'An IGBT merges the simple, low-drive-current insulated gate of a MOSFET with the low conduction losses of a bipolar transistor at high voltage and current, making it the dominant switch in high-power applications like motor drives and inverters.', 'A voltage on the insulated gate creates a conductive channel similar to a MOSFET, which then supplies the base current needed to turn on an internal bipolar transistor structure; the result behaves like a voltage-controlled switch at the gate while conducting collector current with the low saturation voltage characteristic of bipolar devices, which is efficient at high power levels.', 'Motor drive inverters, industrial power supplies, electric vehicle traction inverters, welding equipment and induction heating.', 'Handles much higher voltage and current than a typical MOSFET, simple voltage-controlled gate drive like a MOSFET, low conduction losses at high power.', 'Switches slower than a MOSFET limiting maximum switching frequency, tail current during turn-off causes additional switching loss, overkill and costlier for low-power applications.', NULL, NULL, NULL, '{"Type": "IGBT power switch", "Collector Current": "varies, e.g. 20A-75A common parts", "Collector-Emitter Voltage": "600V-1200V", "Package": "TO-247 / TO-220"}'::jsonb, '{"power electronics","igbt","inverter","high power"}', 'advanced')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
