insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('usb-type-c-connector', 'USB Type-C Connector', 'Connectors', 'Generic', 'Reversible 24-pin USB connector supporting power delivery, high-speed data, and alternate video modes.', 'USB Type-C is a compact, reversible connector standard that has become the near-universal way to power and connect modern electronics, carrying anything from simple 5V charging current up to 100W of Power Delivery and multiple high-speed data protocols.', 'Twenty-four symmetric pins let the plug be inserted either way up, with configuration channel (CC) pins used to negotiate cable orientation, current capability, and Power Delivery voltage between host and device before any power or data lines are fully engaged.', 'Charging and data connections on modern phones, laptops, and dev boards, power delivery for higher-wattage chargers, video output via DisplayPort alternate mode.', 'Reversible orientation removes plug-in guesswork, supports much higher power delivery than older USB connectors, single connector standard across many device types.', 'More complex to design around than simple barrel jacks or older USB connectors, cable and port quality varies widely affecting reliability, negotiating Power Delivery correctly requires dedicated controller ICs.', NULL, NULL, NULL, '{"Pins": "24", "Max Power (USB PD)": "up to 240W (Extended Power Range)", "Data": "USB 2.0/3.x, DisplayPort/Thunderbolt Alt Mode", "Orientation": "Reversible"}'::jsonb, '{"connector","usb-c","power delivery","data"}', 'intermediate')
