insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('jst-xh-connector', 'JST-XH Connector', 'Connectors', 'JST', 'Small locking wire-to-board connector series widely used for battery and low-current signal connections.', 'JST-XH connectors are a 2.5mm pitch locking connector series from JST commonly seen on LiPo battery balance leads, sensor cables, and small power connections where a secure, polarized connection is needed in a compact form.', 'A plastic housing holds crimped or soldered metal terminals in a fixed pitch arrangement, with a mechanical locking tab that prevents accidental disconnection; mating a plug into its matching receptacle establishes multiple parallel electrical contacts simultaneously in a single, polarized insertion.', 'LiPo battery balance connectors, sensor and peripheral cable connections on hobby electronics, small power distribution harnesses.', 'Positive locking prevents accidental disconnection, polarized housing prevents reverse insertion, compact 2.5mm pitch saves board space.', 'Rated for relatively low current so unsuitable for high-power connections, crimping terminals correctly requires a proper crimp tool for reliable connections.', NULL, NULL, NULL, '{"Pitch": "2.5mm", "Current Rating": "~3A per pin", "Pin Counts": "2-15 pin common", "Type": "Wire-to-board / wire-to-wire"}'::jsonb, '{"connector","jst","battery","wire-to-board"}', 'beginner')
