insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('male-header-pins', 'Male Header Pins', 'Connectors', 'Generic', 'Breakaway strip of pins soldered to a PCB to create a breadboard-compatible or jumper-wire connection point.', 'Male header pin strips are one of the most fundamental connectors in electronics prototyping, a row of square metal pins on 2.54mm (0.1 inch) spacing that can be broken to length and soldered onto a PCB to accept female jumper wires or plug into a breadboard.', 'Each pin is simply a rigid metal conductor soldered to a corresponding pad or through-hole on the PCB, providing a direct mechanical and electrical contact point that a female socket, jumper wire, or breadboard hole can grip and make contact with.', 'Breaking out microcontroller GPIO pins for breadboard use, creating jumper wire connection points, building stackable shield-style board interfaces.', 'Extremely cheap and simple, universally compatible with breadboards and jumper wires on standard 0.1 inch pitch, easy to break to any needed length.', 'Exposed pins can short against nearby metal objects, connections can loosen with repeated insertion cycles, not suitable for high-current connections.', NULL, NULL, NULL, '{"Pitch": "2.54mm (0.1in)", "Rows": "Single or double row", "Current Rating": "~1A per pin typical", "Package": "THT breakaway strip"}'::jsonb, '{"connector","header pins","breadboard","prototyping"}', 'beginner')
