insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('dc-barrel-jack', 'DC Barrel Jack', 'Connectors', 'Generic', 'Coaxial power connector used almost universally for wall-adapter DC power input on hobby boards.', 'The DC barrel jack (or coaxial power connector) is the round connector found on the power input of countless dev boards and consumer electronics, mating with a matching barrel plug from a wall adapter to deliver DC power through a simple two-conductor coaxial contact.', 'The connector uses two concentric conductive contacts, an inner pin and an outer sleeve, that align with the corresponding plug''s tip and barrel; standard sizes and center-positive polarity conventions let a wide range of generic wall adapters interoperate with compatible boards, though polarity and size mismatches remain a common wiring hazard.', 'DC power input on Arduino and similar dev boards, powering benchtop electronics from a wall adapter, general low-voltage DC power distribution.', 'Simple mechanical connection that resists accidental disconnection better than bare wires, widely standardized sizes (5.5mm/2.1mm common), inexpensive.', 'No universal polarity standard so mismatched adapters can damage a board, current rating limited compared to locking connectors, size variants are not interchangeable.', NULL, NULL, NULL, '{"Common Size": "5.5mm OD / 2.1mm ID", "Current Rating": "~2A-5A depending on size", "Polarity": "Center-positive common, not standardized", "Package": "THT / panel mount"}'::jsonb, '{"connector","dc jack","power","barrel connector"}', 'beginner')
