insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('female-header-socket', 'Female Header Socket', 'Connectors', 'Generic', 'Socket strip that accepts male header pins, commonly used to create removable module or shield connections.', 'Female header sockets are the mating counterpart to male header pins, providing a row of spring-contact sockets on standard 2.54mm pitch that let modules, shields, or jumper wires be plugged in and removed repeatedly without soldering.', 'Each socket contains a small spring-loaded metal contact that grips an inserted male pin from multiple sides, maintaining reliable electrical contact through spring tension even as the pin is repeatedly inserted and removed.', 'Socketing removable sensor modules and shields, creating swappable microcontroller mounting sockets, breadboard-style prototyping connections.', 'Allows modules to be swapped without desoldering, standard pitch matches nearly all hobby electronics headers, available in many row counts and heights.', 'Contact resistance and reliability degrade with excessive insertion cycles, taller stacking headers add height to a project''s profile.', NULL, NULL, NULL, '{"Pitch": "2.54mm (0.1in)", "Rows": "Single or double row", "Current Rating": "~1A per pin typical", "Package": "THT breakaway strip"}'::jsonb, '{"connector","female header","socket","prototyping"}', 'beginner')
