insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('terminal-block', 'Screw Terminal Block', 'Connectors', 'Phoenix Contact', 'Modular connector that clamps bare or ferruled wire under a screw, giving a solder-free, removable connection.', 'Screw terminal blocks let wires be connected to a PCB or panel without soldering, by tightening a small screw down onto the stripped wire end inside a metal clamp, and are the standard choice wherever field wiring needs to be easily connected or disconnected.', 'Turning the screw drives a metal clamping plate down onto the inserted wire, mechanically compressing it against a fixed contact to create both a secure mechanical grip and a low-resistance electrical connection, without needing any solder.', 'Field wiring for power supplies and motor connections, connecting sensors and actuators in industrial and DIY control panels, removable power input on dev boards.', 'Tool-free (screwdriver only) wire connection and disconnection, handles a range of wire gauges, no soldering skill required.', 'Screws can loosen over time under vibration, bulkier than solder or crimp connections, exposed wire ends can fray or short.', NULL, NULL, NULL, '{"Pitch": "2.54mm-5.08mm common", "Current Rating": "varies, e.g. 8A-15A per terminal", "Wire Gauge": "typically 12-24 AWG", "Package": "THT or panel mount"}'::jsonb, '{"connector","terminal block","screw terminal","wiring"}', 'beginner')
