insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('18650-liion-cell', '18650 Li-ion Cell', 'Batteries', 'Samsung SDI', 'Cylindrical rechargeable lithium-ion cell, 18mm diameter by 65mm long, the workhorse of portable power packs.', 'The 18650 format cylindrical lithium-ion cell offers a strong balance of energy density, cost, and availability, and is used everywhere from laptop battery packs to flashlights to DIY power banks, typically requiring a protection circuit for safe use.', 'During discharge, lithium ions move from the negative graphite electrode through the electrolyte to the positive metal-oxide electrode while electrons flow through the external circuit to do work, and this process reverses during charging as ions migrate back to the negative electrode.', 'DIY battery packs and power banks, flashlight and portable tool power, electric bicycle and scooter battery packs, robotics power supplies.', 'High energy density for its size and weight, rechargeable hundreds of times, widely available and relatively inexpensive per watt-hour.', 'Requires a protection circuit to prevent over-discharge, overcharge, and short circuit, can be a fire risk if physically damaged or improperly charged, unprotected cells are dangerous for beginners.', NULL, NULL, NULL, '{"Nominal Voltage": "3.7V", "Capacity": "1800mAh-3500mAh common", "Chemistry": "Lithium-ion (various cathode types)", "Dimensions": "18mm x 65mm"}'::jsonb, '{"battery","lithium-ion","18650","rechargeable"}', 'advanced')
