insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('lipo-battery-pack', 'LiPo Battery Pack', 'Batteries', 'Turnigy', 'Flexible pouch-style lithium polymer battery pack offering high discharge current in a lightweight package.', 'Lithium polymer (LiPo) battery packs use a gel or solid polymer electrolyte in a flexible foil pouch rather than a rigid metal can, allowing custom shapes and very high discharge rates, making them the standard power source for drones and RC vehicles.', 'Like other lithium-ion chemistries, LiPo cells store energy through the reversible movement of lithium ions between electrodes during charge and discharge, but the polymer or gel electrolyte and flexible pouch construction allow thinner, lighter cells shaped to fit specific product enclosures.', 'Drone and RC vehicle propulsion power, wearable and compact electronics battery packs, high-current robotics power supplies.', 'Very high discharge current capability (high C-rating), flexible form factor and low weight, high energy density.', 'Physically fragile pouch construction can be punctured or swell if damaged, requires careful balanced charging, higher fire risk than more rugged chemistries if mishandled.', NULL, NULL, NULL, '{"Nominal Voltage": "3.7V per cell", "Capacity": "varies, e.g. 500mAh-5000mAh", "C-Rating": "20C-100C common for RC use", "Connector": "JST-XH balance lead common"}'::jsonb, '{"battery","lipo","rechargeable","drone"}', 'advanced')
