insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('9v-battery', '9V Battery', 'Batteries', 'Duracell', 'Rectangular primary or rechargeable battery with a distinctive snap connector, a classic hobby power source.', 'The 9V battery (PP3 size) packages either six small 1.5V primary cells or an equivalent rechargeable stack inside a compact rectangular case with a standardized two-terminal snap connector, long used to power smoke detectors, guitar pedals, and simple hobby circuits.', 'Internally the battery is a series stack of smaller individual cells, most commonly six 1.5V cells wired in series to add their voltages to a nominal 9V, delivered through the two polarized snap terminals on top of the case.', 'Powering breadboard prototypes and simple hobby circuits, smoke detectors, guitar effects pedals, small handheld instruments.', 'Convenient snap connector needs no holder for basic use, widely available everywhere, simple two-terminal polarized connection.', 'Relatively low capacity for its size and cost compared to other formats, primary (non-rechargeable) versions are wasteful for repeated projects, voltage sags noticeably under moderate current draw.', 'https://commons.wikimedia.org/wiki/Special:FilePath/9 volt Battery Snap.jpg', NULL, NULL, '{"Nominal Voltage": "9V", "Capacity": "~500-600mAh (alkaline)", "Chemistry": "Alkaline or NiMH rechargeable", "Connector": "PP3 snap terminals"}'::jsonb, '{"battery","9v","primary cell","power"}', 'beginner')
