insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('cr2032-coin-cell', 'CR2032 Coin Cell', 'Batteries', 'Panasonic', 'Small flat lithium coin cell commonly used for real-time clocks, keyless remotes, and low-drain memory backup.', 'The CR2032 is a 20mm diameter, 3.2mm thick lithium manganese dioxide coin cell that delivers a stable 3V output over a very long shelf life, making it the default choice for real-time clock backup and other extremely low-current always-on applications.', 'A lithium metal anode reacts with a manganese dioxide cathode through a non-aqueous electrolyte, releasing electrons through the external circuit while lithium ions migrate internally; the chemistry gives a flat discharge voltage curve that stays near 3V for most of the cell''s life before dropping off.', 'Real-time clock (RTC) backup power on microcontroller boards, key fobs and remote controls, small LED throwies and blinky projects, coin-cell powered wearables.', 'Very long shelf life measured in years, stable 3V output well suited to directly powering low-power 3V logic, small and lightweight.', 'Very limited total capacity and low maximum discharge current, not rechargeable in the standard CR variant, swallowing hazard requires careful handling around children.', NULL, NULL, NULL, '{"Nominal Voltage": "3V", "Capacity": "~225mAh", "Chemistry": "Lithium manganese dioxide", "Dimensions": "20mm x 3.2mm"}'::jsonb, '{"battery","coin cell","cr2032","lithium"}', 'beginner')
