insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('crystal-oscillator-can', 'Crystal Oscillator (Can/SPXO)', 'Oscillators', 'Abracon', 'Self-contained metal-can module that outputs a stable square-wave clock signal without needing external components.', 'A can oscillator (SPXO) packages a quartz crystal together with its own sustaining amplifier circuit inside a small metal or ceramic case, so it directly outputs a ready-to-use digital clock signal from a single supply pin, unlike a bare crystal which needs external driving circuitry.', 'Internally, an amplifier circuit sustains the quartz crystal''s mechanical resonance through the piezoelectric effect, continuously reinforcing the oscillation at the crystal''s precise resonant frequency, and onboard shaping circuitry converts that oscillation into a clean digital square wave at the output pin.', 'Providing the master clock for microcontrollers and digital logic that need a ready-made clock signal, real-time clock timekeeping references, communication interface baud rate references.', 'No external capacitors or gain stage needed, unlike a bare crystal, very stable and accurate frequency output, simple 4-pin drop-in usage.', 'More expensive than a bare crystal, larger footprint than a crystal alone, fixed frequency cannot be trimmed after manufacture.', NULL, NULL, NULL, '{"Frequency Range": "32kHz-100MHz+ depending on part", "Stability": "+/-20 to +/-100 ppm typical", "Supply Voltage": "3.3V/5V", "Package": "4-pin metal can (SMD or THT)"}'::jsonb, '{"oscillator","crystal oscillator","clock","timing"}', 'intermediate')
on conflict (slug) do update set
  name = excluded.name, category = excluded.category, manufacturer = excluded.manufacturer,
  short_description = excluded.short_description, long_description = excluded.long_description,
