insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('ceramic-resonator', 'Ceramic Resonator', 'Oscillators', 'Murata', 'Three-terminal frequency-determining component using a ceramic piezoelectric element, cheaper than quartz but less precise.', 'Ceramic resonators use a piezoelectric ceramic element instead of quartz to set an oscillation frequency, often with built-in load capacitors in a compact three-pin package, trading some frequency accuracy for lower cost and simpler external circuitry compared to a crystal.', 'The ceramic element mechanically resonates at a characteristic frequency through the piezoelectric effect, similarly to a quartz crystal, and when paired with an on-chip or external oscillator amplifier circuit it sustains that resonance to generate a stable clock signal, though with wider tolerance and more temperature drift than quartz.', 'Clock source for cost-sensitive microcontroller designs, IR remote control carrier frequency generation, non-critical timing references in consumer electronics.', 'Cheaper than an equivalent quartz crystal, often includes built-in load capacitors simplifying the circuit, faster startup time than crystals.', 'Less accurate and more temperature-sensitive than quartz crystals, unsuitable for precision timekeeping applications like real-time clocks.', NULL, NULL, NULL, '{"Frequency Range": "400kHz-60MHz common", "Stability": "+/-0.5% typical", "Package": "3-pin THT or SMD"}'::jsonb, '{"oscillator","ceramic resonator","clock","timing"}', 'intermediate')
