insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('rc-relaxation-oscillator', 'RC Relaxation Oscillator (555-based)', 'Oscillators', 'Texas Instruments', 'Simple oscillator circuit built from a timer IC and an external resistor-capacitor network to set frequency.', 'Rather than a dedicated single-part oscillator, an RC relaxation oscillator is commonly built using a 555 timer wired in astable mode, where charging and discharging an external capacitor through resistors repeatedly triggers the output to flip, generating a continuous square wave.', 'The timer repeatedly charges an external capacitor through resistors until it crosses an upper voltage threshold, at which point internal circuitry flips the output and begins discharging the capacitor until it crosses a lower threshold, restarting the cycle; the resistor and capacitor values directly set the oscillation frequency and duty cycle.', 'Low-cost tone and blink generators, PWM signal generation for motor speed or LED brightness control, simple clock sources where crystal precision is not required.', 'Extremely cheap using just a timer IC and a couple of passive components, frequency and duty cycle are easily adjusted by changing resistor and capacitor values.', 'Frequency accuracy and stability are far worse than crystal-based oscillators, drifts with temperature and supply voltage changes.', NULL, NULL, NULL, '{"Frequency Range": "depends on RC values, from <1Hz to >100kHz", "Stability": "Low, several percent drift typical", "Core Component": "555 Timer IC"}'::jsonb, '{"oscillator","555 timer","rc circuit","astable"}', 'beginner')
