insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('16mhz-quartz-crystal', '16MHz Quartz Crystal', 'Crystals', 'Abracon', 'Bare two-terminal quartz crystal resonating at 16MHz, the classic clock source for the Arduino Uno''s ATmega328P.', 'This small two-lead quartz crystal vibrates at a precise 16MHz frequency when driven by an external oscillator circuit, and is the exact part soldered onto an Arduino Uno alongside two small load capacitors to generate the microcontroller''s system clock.', 'The quartz element exhibits the piezoelectric effect, mechanically deforming when an electric field is applied and generating a voltage when mechanically stressed; paired with an external inverting amplifier (usually built into the microcontroller) and two load capacitors, this property is exploited to sustain a highly stable oscillation at the crystal''s natural resonant frequency.', 'System clock source for AVR and other microcontrollers, precise timing references in digital circuits, UART baud rate generation.', 'Very high frequency accuracy and stability compared to RC or ceramic oscillators, extremely low cost, tiny two-terminal footprint.', 'Needs an external amplifier circuit and load capacitors to actually oscillate, unlike a self-contained can oscillator, more fragile than a packaged oscillator module.', NULL, NULL, NULL, '{"Frequency": "16MHz", "Load Capacitance": "18pF-22pF typical", "Tolerance": "+/-20 to +/-30 ppm", "Package": "HC-49 THT or SMD"}'::jsonb, '{"crystal","quartz","16mhz","clock source"}', 'intermediate')
