insert into public.components (slug, name, category, manufacturer, short_description, long_description, working_principle, applications, advantages, disadvantages, image_url, model_url, datasheet_url, specs, tags, difficulty) values
  ('32768hz-watch-crystal', '32.768kHz Watch Crystal', 'Crystals', 'Epson', 'Tiny low-frequency crystal used almost universally to drive real-time clocks and timekeeping circuits.', 'The 32.768kHz tuning-fork crystal is chosen specifically because that frequency, when divided by 15 stages of binary division (2 to the 15th power), yields exactly one pulse per second, making it the standard timekeeping reference in real-time clock chips, wristwatches, and microcontroller sleep timers.', 'A tiny tuning-fork shaped quartz element vibrates at 32.768kHz through the piezoelectric effect when sustained by an oscillator circuit; a simple 15-stage binary counter then divides that frequency down by exactly 32768, producing a clean one-pulse-per-second output ideal for counting seconds.', 'Real-time clock IC timekeeping reference, microcontroller low-power sleep and wake timers, wristwatch and clock movement timing.', 'The 32768 = 2^15 relationship makes generating an exact one-second tick trivial with simple binary counters, extremely low power consumption suited to battery-backed timekeeping.', 'Very low frequency makes it unsuitable as a general system clock, tuning-fork crystals are mechanically delicate and sensitive to shock.', NULL, NULL, NULL, '{"Frequency": "32.768kHz", "Load Capacitance": "6pF-12.5pF typical", "Tolerance": "+/-20 ppm typical", "Package": "Cylindrical or SMD tuning fork"}'::jsonb, '{"crystal","watch crystal","rtc","32768hz"}', 'intermediate')
